// 錯題複習資料，由 tools/import_mistakes.py 從 review/*.md 產生，勿手改
const MISTAKES = [{"id": "Carol Bai 多益文法 Part 5#Day1-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day1-Q1", "q": "The new employee's ______ is to design a new product component for the company.", "opts": ["assignment", "assigned", "assignee", "assigning"], "ans": 0, "exp": "所有格 employee's 之後、動詞 is 之前需要名詞當主詞，「任務」用 assignment。", "tags": ["詞性", "名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day3-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day3-Q1", "q": "The entire team is ______ for the project's outcome.", "opts": ["response", "responsibleness", "responsible", "respond"], "ans": 2, "exp": "be 動詞後接形容詞當主詞補語，responsible（負責的）；response 是名詞、respond 是動詞。", "tags": ["詞性", "形容詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day4-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day4-Q1", "q": "When we discuss the new marketing plan, let's do it ______.", "opts": ["creatively", "creative", "creativity", "creation"], "ans": 0, "exp": "修飾動詞 do 要用副詞 creatively（有創意地）。", "tags": ["詞性", "副詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day5-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day5-Q1", "q": "The ______ nature of the project makes it challenging to complete on time.", "opts": ["complexity", "complex", "complexify", "complexness"], "ans": 1, "exp": "名詞 nature 前需形容詞修飾，complex（複雜的）。", "tags": ["詞性", "形容詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day5-Q2", "src": "Carol Bai 多益文法 Part 5", "no": "Day5-Q2", "q": "Management appreciates employees who ______ new initiatives to improve the company's operations.", "opts": ["proposal", "proposer", "proposing", "propose"], "ans": 3, "exp": "關係代名詞 who 引導的子句需要動詞，先行詞 employees 為複數用原形 propose。", "tags": ["詞性", "動詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day5-Q3", "src": "Carol Bai 多益文法 Part 5", "no": "Day5-Q3", "q": "The company's success is directly tied to the ______ of its employees.", "opts": ["product", "productive", "productivity", "production"], "ans": 2, "exp": "冠詞 the 之後、of 之前需要名詞，此處指員工的「生產力」productivity。", "tags": ["詞性", "名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day6-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day6-Q1", "q": "My boss usually ______ early on Fridays.", "opts": ["has left", "is leaving", "leaves", "has been leaving"], "ans": 2, "exp": "usually 表習慣，用現在簡單式；主詞第三人稱單數用 leaves。", "tags": ["時態", "現在式"]}, {"id": "Carol Bai 多益文法 Part 5#Day7-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day7-Q1", "q": "We ______ a new supplier last month. Their prices are much better.", "opts": ["had found", "were finding", "found", "had been finding"], "ans": 2, "exp": "last month 是明確的過去時間，用過去簡單式 found。", "tags": ["時態", "過去式"]}, {"id": "Carol Bai 多益文法 Part 5#Day7-Q2", "src": "Carol Bai 多益文法 Part 5", "no": "Day7-Q2", "q": "Sorry for being late. I ______ some emails before leaving the office.", "opts": ["answered", "was answering", "had answered", "had been answering"], "ans": 0, "exp": "單純敘述過去發生的動作，用過去簡單式 answered。", "tags": ["時態", "過去式"]}, {"id": "Carol Bai 多益文法 Part 5#Day8-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day8-Q1", "q": "How long ______ the presentation before the meeting starts?", "opts": ["will you prepare", "will you be preparing", "will you have prepared", "will you have been preparing"], "ans": 3, "exp": "問到未來某時點（會議開始前）為止「已持續多久」，用未來完成進行式。", "tags": ["時態", "未來式"]}, {"id": "Carol Bai 多益文法 Part 5#Day8-Q2", "src": "Carol Bai 多益文法 Part 5", "no": "Day8-Q2", "q": "By the time we arrive, they ______ the contract.", "opts": ["will have signed", "will be signing", "will have been signing", "will have been signed"], "ans": 0, "exp": "By the time + 現在式子句，主句用未來完成式，表在到達前已完成。", "tags": ["時態", "未來完成式"]}, {"id": "Carol Bai 多益文法 Part 5#Day9-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day9-Q1", "q": "My team and I ______ a new project proposal tomorrow.", "opts": ["present", "are presenting", "have presented", "have been presenting"], "ans": 1, "exp": "tomorrow 表已安排好的計畫，用現在進行式表未來 are presenting。", "tags": ["時態", "未來式"]}, {"id": "Carol Bai 多益文法 Part 5#Day10-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day10-Q1", "q": "Our competitors launched a new product, and ______ quickly became popular in the market.", "opts": ["it", "they", "them", "their"], "ans": 0, "exp": "指前面單數的 a new product，當主詞用主格 it。", "tags": ["代名詞", "主格"]}, {"id": "Carol Bai 多益文法 Part 5#Day10-Q2", "src": "Carol Bai 多益文法 Part 5", "no": "Day10-Q2", "q": "The CEO has announced a new policy, and ______ will be implemented starting next month.", "opts": ["they", "it", "them", "their"], "ans": 1, "exp": "指單數的 a new policy，當主詞用主格 it。", "tags": ["代名詞", "主格"]}, {"id": "Carol Bai 多益文法 Part 5#Day11-Q5", "src": "Carol Bai 多益文法 Part 5", "no": "Day11-Q5", "q": "The CEO commended the team for ______ hard work and dedication to the project.", "opts": ["theirs", "it's", "their", "him"], "ans": 2, "exp": "修飾名詞 hard work 需所有格，指複數 the team 用 their。", "tags": ["代名詞", "所有格"]}, {"id": "Carol Bai 多益文法 Part 5#Day11-Q6", "src": "Carol Bai 多益文法 Part 5", "no": "Day11-Q6", "q": "The sales department is responsible for meeting ______ monthly targets.", "opts": ["its", "it's", "there", "theirs"], "ans": 0, "exp": "所有格修飾 monthly targets，指單數 department 用 its；it's 是 it is 的縮寫。", "tags": ["代名詞", "所有格"]}, {"id": "Carol Bai 多益文法 Part 5#Day12-Q8", "src": "Carol Bai 多益文法 Part 5", "no": "Day12-Q8", "q": "The team members discussed their individual tasks, and ______ were completed on time.", "opts": ["mine", "theirs", "my", "me"], "ans": 1, "exp": "theirs = their tasks，用所有格代名詞代替前面提到的名詞當主詞。", "tags": ["代名詞", "所有格代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day13-Q12", "src": "Carol Bai 多益文法 Part 5", "no": "Day13-Q12", "q": "The company values its employees and offers ______ various benefits and opportunities for growth.", "opts": ["they", "them", "their", "themselves"], "ans": 1, "exp": "動詞 offers 的受詞，指 employees 用受格 them。", "tags": ["代名詞", "受格"]}, {"id": "Carol Bai 多益文法 Part 5#Day14-Q16", "src": "Carol Bai 多益文法 Part 5", "no": "Day14-Q16", "q": "As a team, we take ownership of our work. We challenge ______ to be the best in our industry.", "opts": ["oneself", "yourselves", "ourselves", "itself"], "ans": 2, "exp": "主詞 we 與受詞為同一群人，用反身代名詞 ourselves。", "tags": ["代名詞", "反身代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day14-Q17", "src": "Carol Bai 多益文法 Part 5", "no": "Day14-Q17", "q": "Mary prepared the presentation for the conference ______.", "opts": ["myself", "itself", "herself", "her"], "ans": 2, "exp": "強調 Mary「親自」完成，用反身代名詞 herself。", "tags": ["代名詞", "反身代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day15-Q24", "src": "Carol Bai 多益文法 Part 5", "no": "Day15-Q24", "q": "The new advertising campaign generated more leads than ______ used in the past.", "opts": ["whose", "those", "what", "which"], "ans": 1, "exp": "代替前面複數名詞 leads，用 those（= the leads that were used）。", "tags": ["代名詞", "指示代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day16-Q30", "src": "Carol Bai 多益文法 Part 5", "no": "Day16-Q30", "q": "The new marketing strategy resulted in a higher conversion rate than ______ of the previous campaigns.", "opts": ["them", "they", "that", "their"], "ans": 2, "exp": "代替單數名詞 conversion rate，用 that 避免重複（than that of…）。", "tags": ["代名詞", "指示代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day16-Q31", "src": "Carol Bai 多益文法 Part 5", "no": "Day16-Q31", "q": "Company XYZ's customer retention rate is higher than ______ of its competitors.", "opts": ["that", "they", "them", "their"], "ans": 0, "exp": "代替單數名詞 rate，用 that（than that of…）。", "tags": ["代名詞", "指示代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day17-Q34", "src": "Carol Bai 多益文法 Part 5", "no": "Day17-Q34", "q": "The company's new advertising campaign is targeted at ______ who belongs to the 18-35 age group.", "opts": ["anything", "anyone", "any", "another"], "ans": 1, "exp": "指「任何人」用 anyone，後接 who 引導的形容詞子句。", "tags": ["代名詞", "不定代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day17-Q35", "src": "Carol Bai 多益文法 Part 5", "no": "Day17-Q35", "q": "______ interested in attending the conference should register online before the deadline.", "opts": ["Anything", "Another", "Any", "Anyone"], "ans": 3, "exp": "句首當主詞，指「任何有興趣的人」用 Anyone。", "tags": ["代名詞", "不定代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day18-Q38", "src": "Carol Bai 多益文法 Part 5", "no": "Day18-Q38", "q": "Despite offering an incentive, ______ signed up for the training session on advanced sales techniques.", "opts": ["nobody", "several", "everybody", "anyone"], "ans": 0, "exp": "儘管提供誘因卻「沒有人」報名，前後語意轉折用 nobody。", "tags": ["代名詞", "不定代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day18-Q39", "src": "Carol Bai 多益文法 Part 5", "no": "Day18-Q39", "q": "______ knew about the impending merger between the two companies until the official announcement was made.", "opts": ["Somebody", "Nobody", "Everyone", "Anybody"], "ans": 1, "exp": "直到正式宣布前「沒有人」知道，用 Nobody。", "tags": ["代名詞", "不定代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day19-Q42", "src": "Carol Bai 多益文法 Part 5", "no": "Day19-Q42", "q": "In the survey, it was found that ______ clients prefer to communicate via email.", "opts": ["majority", "almost", "most", "the most"], "ans": 2, "exp": "most + 複數名詞 = 大多數的…，most clients；majority 需 the majority of，almost 是副詞。", "tags": ["代名詞", "不定形容詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day19-Q43", "src": "Carol Bai 多益文法 Part 5", "no": "Day19-Q43", "q": "______ of the participants rated the conference venue as excellent.", "opts": ["Much all", "Most", "Much", "The most"], "ans": 1, "exp": "most of the + 名詞，用 Most；majority 要 the majority of，much 修飾不可數。", "tags": ["代名詞", "不定代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day19-Q44", "src": "Carol Bai 多益文法 Part 5", "no": "Day19-Q44", "q": "The sales team discovered that ______ customers are interested in the new product.", "opts": ["majority", "almost", "the most", "most"], "ans": 3, "exp": "most + 複數名詞 customers，表「大多數的」。", "tags": ["代名詞", "不定形容詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day20-Q47", "src": "Carol Bai 多益文法 Part 5", "no": "Day20-Q47", "q": "______ the economic downturn, the company managed to achieve record sales figures last quarter.", "opts": ["Throughout", "Besides", "Despite", "Versus"], "ans": 2, "exp": "後接名詞片語 the economic downturn，表「儘管」用介系詞 Despite。", "tags": ["介系詞", "despite"]}, {"id": "Carol Bai 多益文法 Part 5#Day20-Q48", "src": "Carol Bai 多益文法 Part 5", "no": "Day20-Q48", "q": "The marketing campaign was successful, ______ the limited budget allocated for it.", "opts": ["beyond", "despite", "throughout", "above"], "ans": 1, "exp": "後接名詞片語表讓步「儘管預算有限」，用 despite。", "tags": ["介系詞", "despite"]}, {"id": "Carol Bai 多益文法 Part 5#Day21-Q54", "src": "Carol Bai 多益文法 Part 5", "no": "Day21-Q54", "q": "All employees must submit their expense reports ______ the end of the month.", "opts": ["between", "before", "beyond", "through"], "ans": 1, "exp": "在月底「之前」提交，用 before。", "tags": ["介系詞", "before"]}, {"id": "Carol Bai 多益文法 Part 5#Day22-Q60", "src": "Carol Bai 多益文法 Part 5", "no": "Day22-Q60", "q": "The company's new product must be launched ______ two months to meet the market demand.", "opts": ["within", "except", "along", "amid"], "ans": 0, "exp": "表「在兩個月之內」用 within。", "tags": ["介系詞", "within"]}, {"id": "Carol Bai 多益文法 Part 5#Day22-Q62", "src": "Carol Bai 多益文法 Part 5", "no": "Day22-Q62", "q": "The sales team managed to close the deal ______ a few days of negotiations.", "opts": ["besides", "during", "among", "within"], "ans": 3, "exp": "表在「一段時間之內」完成，用 within a few days。", "tags": ["介系詞", "within"]}, {"id": "Carol Bai 多益文法 Part 5#Day23-Q66", "src": "Carol Bai 多益文法 Part 5", "no": "Day23-Q66", "q": "The new marketing campaign is designed ______ increasing brand awareness in the target market.", "opts": ["above", "for", "without", "upon"], "ans": 1, "exp": "be designed for + 動名詞，表目的用 for。", "tags": ["介系詞", "for"]}, {"id": "Carol Bai 多益文法 Part 5#Day23-Q67", "src": "Carol Bai 多益文法 Part 5", "no": "Day23-Q67", "q": "The company has allocated a budget ______ research and development of new products.", "opts": ["since", "for", "on", "behind"], "ans": 1, "exp": "撥預算「用於」研發，用 for。", "tags": ["介系詞", "for"]}, {"id": "Carol Bai 多益文法 Part 5#Day24-Q71", "src": "Carol Bai 多益文法 Part 5", "no": "Day24-Q71", "q": "The marketing team is currently working ______ a new advertising campaign to promote the latest product.", "opts": ["of", "in", "for", "on"], "ans": 3, "exp": "work on「著手進行、致力於」，固定搭配用 on。", "tags": ["介系詞", "on"]}, {"id": "Carol Bai 多益文法 Part 5#Day25-Q77", "src": "Carol Bai 多益文法 Part 5", "no": "Day25-Q77", "q": "The marketing team successfully promoted the new product ______ social media platforms.", "opts": ["unlike", "around", "through", "within"], "ans": 2, "exp": "透過社群平台，表「透過某媒介」用 through。", "tags": ["介系詞", "through"]}, {"id": "Carol Bai 多益文法 Part 5#Day26-Q82", "src": "Carol Bai 多益文法 Part 5", "no": "Day26-Q82", "q": "Our company experienced a surge in website traffic ______ the holiday season, thanks to our special promotions.", "opts": ["during", "without", "since", "down"], "ans": 0, "exp": "during + 表期間的名詞（the holiday season），表「在…期間」。", "tags": ["介系詞", "during"]}, {"id": "Carol Bai 多益文法 Part 5#Day26-Q83", "src": "Carol Bai 多益文法 Part 5", "no": "Day26-Q83", "q": "______ the conference, there will be networking sessions to connect industry professionals.", "opts": ["Under", "Behind", "During", "Across"], "ans": 2, "exp": "During + 名詞，表「在…期間」。", "tags": ["介系詞", "during"]}, {"id": "Carol Bai 多益文法 Part 5#Day27-Q87", "src": "Carol Bai 多益文法 Part 5", "no": "Day27-Q87", "q": "The strategic partnership aims to enhance collaboration ______ our research and development teams and academic institutions.", "opts": ["through", "beside", "between", "under"], "ans": 2, "exp": "between A and B，兩方之間的合作用 between。", "tags": ["介系詞", "between"]}, {"id": "Carol Bai 多益文法 Part 5#Day28-Q93", "src": "Carol Bai 多益文法 Part 5", "no": "Day28-Q93", "q": "All invoices must be paid ______ the designated due date to avoid any late fees.", "opts": ["on", "by", "within", "through"], "ans": 1, "exp": "在期限前（不遲於）付清，用 by。", "tags": ["介系詞", "by"]}, {"id": "Carol Bai 多益文法 Part 5#Day29-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day29-Q1", "q": "______ market research, the new product has a high potential for success.", "opts": ["According to", "In case of", "Without", "Opposite to"], "ans": 0, "exp": "根據市場調查，用 According to。", "tags": ["介系詞", "according to"]}, {"id": "Carol Bai 多益文法 Part 5#Day29-Q3", "src": "Carol Bai 多益文法 Part 5", "no": "Day29-Q3", "q": "All project expenses must be managed ______ established budget guidelines.", "opts": ["in favor of", "in accordance with", "in front of", "in order that"], "ans": 1, "exp": "依照既定規範，用 in accordance with（依照…）。", "tags": ["介系詞", "in accordance with"]}, {"id": "Carol Bai 多益文法 Part 5#Day30-Q6", "src": "Carol Bai 多益文法 Part 5", "no": "Day30-Q6", "q": "The conference attendees will not be granted access to the seminar room ______ a valid registration badge.", "opts": ["considering", "with", "through", "without"], "ans": 3, "exp": "沒有有效證件就不得進入，用 without。", "tags": ["介系詞", "without"]}, {"id": "Carol Bai 多益文法 Part 5#Day30-Q7", "src": "Carol Bai 多益文法 Part 5", "no": "Day30-Q7", "q": "The company cannot finalize the contract ______ the client's signature.", "opts": ["below", "above", "without", "across"], "ans": 2, "exp": "沒有客戶簽名就無法定案，用 without。", "tags": ["介系詞", "without"]}, {"id": "Carol Bai 多益文法 Part 5#Day31-Q11", "src": "Carol Bai 多益文法 Part 5", "no": "Day31-Q11", "q": "The vendor requires payment to be made ______ the delivery of the goods.", "opts": ["because of", "prior to", "due to", "apart from"], "ans": 1, "exp": "在交貨「之前」付款，用 prior to（= before）。", "tags": ["介系詞", "prior to"]}, {"id": "Carol Bai 多益文法 Part 5#Day31-Q12", "src": "Carol Bai 多益文法 Part 5", "no": "Day31-Q12", "q": "The team needs to complete the project plan ______ the client presentation.", "opts": ["prior to", "along with", "regardless of", "as for"], "ans": 0, "exp": "在客戶簡報「之前」完成，用 prior to。", "tags": ["介系詞", "prior to"]}, {"id": "Carol Bai 多益文法 Part 5#Day32-Q16", "src": "Carol Bai 多益文法 Part 5", "no": "Day32-Q16", "q": "In order to achieve sustainable growth, our company must look for opportunities that go ______ our current market reach.", "opts": ["beyond", "within", "through", "beneath"], "ans": 0, "exp": "go beyond「超越」既有市場範圍。", "tags": ["介系詞", "beyond"]}, {"id": "Carol Bai 多益文法 Part 5#Day32-Q17", "src": "Carol Bai 多益文法 Part 5", "no": "Day32-Q17", "q": "All items are currently on sale for 20% off ______ the new arrivals in the \"Latest Trends\" section.", "opts": ["alongside", "throughout", "except", "beneath"], "ans": 2, "exp": "除了新品「之外」皆打折，用 except。", "tags": ["介系詞", "except"]}, {"id": "Carol Bai 多益文法 Part 5#Day33-Q21", "src": "Carol Bai 多益文法 Part 5", "no": "Day33-Q21", "q": "The marketing presentation has been rescheduled and will take place on Friday, ______ Thursday.", "opts": ["therefore", "but", "since", "instead of"], "ans": 3, "exp": "改到週五「而非」週四，用 instead of。", "tags": ["介系詞", "instead of"]}, {"id": "Carol Bai 多益文法 Part 5#Day33-Q22", "src": "Carol Bai 多益文法 Part 5", "no": "Day33-Q22", "q": "The new software interface is intuitive and user-friendly, ______ the previous version which was complex and hard to navigate.", "opts": ["unlike", "alongside", "within", "beyond"], "ans": 0, "exp": "與舊版「不同」，用 unlike。", "tags": ["介系詞", "unlike"]}, {"id": "Carol Bai 多益文法 Part 5#Day34-Q26", "src": "Carol Bai 多益文法 Part 5", "no": "Day34-Q26", "q": "The workshop on effective communication skills is conducted by experts ______ the renowned Communication Excellence Institute.", "opts": ["by", "from", "within", "into"], "ans": 1, "exp": "來自某機構的專家，表來源用 from。", "tags": ["介系詞", "from"]}, {"id": "Carol Bai 多益文法 Part 5#Day35-Q31", "src": "Carol Bai 多益文法 Part 5", "no": "Day35-Q31", "q": "The manager should meet with the team ______ discussing the new project.", "opts": ["back to", "when", "between", "in part"], "ans": 1, "exp": "when + V-ing，表「在…的時候」when discussing。", "tags": ["介系詞", "when"]}, {"id": "Carol Bai 多益文法 Part 5#Day35-Q33", "src": "Carol Bai 多益文法 Part 5", "no": "Day35-Q33", "q": "The new advertising campaign aims to make our product stand ______ among competitors in the market.", "opts": ["with", "against", "through", "out"], "ans": 3, "exp": "stand out「脫穎而出」，片語動詞用 out。", "tags": ["片語", "stand out"]}, {"id": "Carol Bai 多益文法 Part 5#Day37-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day37-Q1", "q": "All project proposals must be submitted ______ two weeks from today's date.", "opts": ["among", "within", "unless", "while"], "ans": 1, "exp": "在兩週「之內」提交，用 within。", "tags": ["介系詞", "within"]}, {"id": "Carol Bai 多益文法 Part 5#Day37-Q2", "src": "Carol Bai 多益文法 Part 5", "no": "Day37-Q2", "q": "______ the contract, the project should be completed within six months.", "opts": ["Apart from", "Instead of", "According to", "Due to"], "ans": 2, "exp": "根據合約規定，用 According to。", "tags": ["介系詞", "according to"]}, {"id": "Carol Bai 多益文法 Part 5#Day38-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day38-Q1", "q": "______ he is negotiating with other companies, Henry intends to stay with our organization.", "opts": ["Prior to", "From", "Although", "Perhaps"], "ans": 2, "exp": "後接完整子句表讓步「雖然」，用連接詞 Although；Prior to/From 是介系詞。", "tags": ["連接詞", "although"]}, {"id": "Carol Bai 多益文法 Part 5#Day38-Q2", "src": "Carol Bai 多益文法 Part 5", "no": "Day38-Q2", "q": "______ the market research was thorough, the product launch failed to meet expectations.", "opts": ["Although", "Conversely", "Nevertheless", "Accordingly"], "ans": 0, "exp": "雖然市調徹底，結果仍失敗，用讓步連接詞 Although；其餘為副詞。", "tags": ["連接詞", "although"]}, {"id": "Carol Bai 多益文法 Part 5#Day38-Q3", "src": "Carol Bai 多益文法 Part 5", "no": "Day38-Q3", "q": "The company is willing to consider applicants for the management position ______ they lack a formal degree.", "opts": ["except for", "even if", "along with", "in spite of"], "ans": 1, "exp": "後接子句表「即使」，用連接詞 even if；in spite of / except for 後接名詞。", "tags": ["連接詞", "even if"]}, {"id": "Carol Bai 多益文法 Part 5#Day39-Q6", "src": "Carol Bai 多益文法 Part 5", "no": "Day39-Q6", "q": "______ Emily excels in marketing, her colleague Jack specializes in market research.", "opts": ["In case", "As if", "While", "Whether"], "ans": 2, "exp": "對比兩人專長，用 While（然而、相對地）。", "tags": ["連接詞", "while"]}, {"id": "Carol Bai 多益文法 Part 5#Day39-Q7", "src": "Carol Bai 多益文法 Part 5", "no": "Day39-Q7", "q": "______ the sales team focuses on international markets, the marketing team concentrates on domestic strategies.", "opts": ["Only if", "In case", "When", "While"], "ans": 3, "exp": "對比兩個團隊的重點，用 While。", "tags": ["連接詞", "while"]}, {"id": "Carol Bai 多益文法 Part 5#Day40-Q11", "src": "Carol Bai 多益文法 Part 5", "no": "Day40-Q11", "q": "The presentation was rescheduled to next Tuesday ______ that the team could finalize the sales figures.", "opts": ["however", "when", "rather", "so"], "ans": 3, "exp": "so that 引導目的子句「以便」，此處空格填 so。", "tags": ["連接詞", "so that"]}, {"id": "Carol Bai 多益文法 Part 5#Day40-Q12", "src": "Carol Bai 多益文法 Part 5", "no": "Day40-Q12", "q": "Please complete the financial report by Friday afternoon ______ the audit team can review it over the weekend.", "opts": ["so that", "in order to", "that is", "in case of"], "ans": 0, "exp": "後接完整子句表目的，用 so that；in order to 後接原形動詞。", "tags": ["連接詞", "so that"]}, {"id": "Carol Bai 多益文法 Part 5#Day41-Q16", "src": "Carol Bai 多益文法 Part 5", "no": "Day41-Q16", "q": "Robert Garrison has been the company's legal counsel ______ it was established.", "opts": ["ever", "before", "since", "nonetheless"], "ans": 2, "exp": "現在完成式 + since + 子句，表「自從…以來」。", "tags": ["連接詞", "since"]}, {"id": "Carol Bai 多益文法 Part 5#Day41-Q17", "src": "Carol Bai 多益文法 Part 5", "no": "Day41-Q17", "q": "______ the recent merger, we now have openings for several key positions.", "opts": ["Beneath", "Since", "Until", "Despite"], "ans": 1, "exp": "由於近期合併（表原因），用 Since。", "tags": ["連接詞", "since"]}, {"id": "Carol Bai 多益文法 Part 5#Day42-Q21", "src": "Carol Bai 多益文法 Part 5", "no": "Day42-Q21", "q": "______ the conference call, Mr. Johnson will provide updates on the project.", "opts": ["After", "Now", "Soon", "Next"], "ans": 0, "exp": "電話會議「之後」提供最新進度，用 After。", "tags": ["連接詞", "after"]}, {"id": "Carol Bai 多益文法 Part 5#Day43-Q27", "src": "Carol Bai 多益文法 Part 5", "no": "Day43-Q27", "q": "The company is planning to expand its operations to China, ______ it is still facing some challenges.", "opts": ["despite", "or", "but", "either"], "ans": 2, "exp": "前後語意轉折，用對等連接詞 but。", "tags": ["連接詞", "but"]}, {"id": "Carol Bai 多益文法 Part 5#Day44-Q31", "src": "Carol Bai 多益文法 Part 5", "no": "Day44-Q31", "q": "This seminar is designed for entrepreneurs ______ executives seeking innovative strategies.", "opts": ["nevertheless", "rather", "as well as", "albeit"], "ans": 2, "exp": "連接兩個並列名詞 entrepreneurs 與 executives，用 as well as。", "tags": ["連接詞", "as well as"]}, {"id": "Carol Bai 多益文法 Part 5#Day44-Q32", "src": "Carol Bai 多益文法 Part 5", "no": "Day44-Q32", "q": "The training program caters to entry-level employees ______ mid-level managers eager to enhance their skills.", "opts": ["as well as", "while", "therefore", "similarly"], "ans": 0, "exp": "連接兩類並列對象，用 as well as（以及）。", "tags": ["連接詞", "as well as"]}, {"id": "Carol Bai 多益文法 Part 5#Day45-Q37", "src": "Carol Bai 多益文法 Part 5", "no": "Day45-Q37", "q": "______ a customer fails to provide a valid purchase receipt, the return process cannot be initiated.", "opts": ["Except", "So", "That", "If"], "ans": 3, "exp": "條件句「如果…就無法…」，用 If。", "tags": ["連接詞", "if"]}, {"id": "Carol Bai 多益文法 Part 5#Day46-Q41", "src": "Carol Bai 多益文法 Part 5", "no": "Day46-Q41", "q": "Corporate reports must be submitted to the board ______ the financial quarter concludes.", "opts": ["once", "soon", "often", "usually"], "ans": 0, "exp": "once 當連接詞引導時間子句「一旦…就」；soon/often/usually 是副詞。", "tags": ["連接詞", "once"]}, {"id": "Carol Bai 多益文法 Part 5#Day46-Q42", "src": "Carol Bai 多益文法 Part 5", "no": "Day46-Q42", "q": "The project manager will finalize the budget ______ the financial analysis is complete.", "opts": ["overall", "due to", "once", "soon"], "ans": 2, "exp": "once 引導時間子句「一旦…完成」；due to 後接名詞、overall/soon 為副詞。", "tags": ["連接詞", "once"]}, {"id": "Carol Bai 多益文法 Part 5#Day1-Q2", "src": "Carol Bai 多益文法 Part 5", "no": "Day1-Q2", "q": "The deadline for submitting the project analysis is next Friday. Please make sure to meet the ______.", "opts": ["datable", "dating", "deadline", "deadliness"], "ans": 2, "exp": "meet the deadline「趕上截止期限」，空格需名詞 deadline。", "tags": ["詞性", "名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day2-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Day2-Q1", "q": "If you want to ______ your claim, you need to provide more evidence.", "opts": ["substantiate", "substantial", "substance", "substantially"], "ans": 0, "exp": "受詞 your claim 前需動詞，substantiate「證實、證明」；substantial 形容詞、substance 名詞。", "tags": ["詞性", "動詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day3-Q2", "src": "Carol Bai 多益文法 Part 5", "no": "Day3-Q2", "q": "Our sales team needs to be ______ in their approach to customers to increase satisfaction.", "opts": ["proactive", "proactivity", "proactiveness", "proactively"], "ans": 0, "exp": "be 動詞後接形容詞當補語，proactive「積極主動的」。", "tags": ["詞性", "形容詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day4-Q2", "src": "Carol Bai 多益文法 Part 5", "no": "Day4-Q2", "q": "Our company holds meetings ______ to ensure that everyone is well informed.", "opts": ["regularity", "regularly", "regular", "regulate"], "ans": 1, "exp": "修飾動詞 holds 用副詞 regularly「定期地」。", "tags": ["詞性", "副詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day13-Q13", "src": "Carol Bai 多益文法 Part 5", "no": "Day13-Q13", "q": "The company provided ______ with a comprehensive training program to enhance their skills.", "opts": ["they", "their", "them", "themselves"], "ans": 2, "exp": "provide sb with sth，動詞的受詞用受格 them。", "tags": ["代名詞", "受格"]}, {"id": "Carol Bai 多益文法 Part 5#Day15-Q23", "src": "Carol Bai 多益文法 Part 5", "no": "Day15-Q23", "q": "Our company's customer satisfaction ratings are higher than ______ of our main rivals.", "opts": ["which", "whose", "what", "those"], "ans": 3, "exp": "代替前面複數名詞 ratings，用 those（than those of…）。", "tags": ["代名詞", "指示代名詞"]}, {"id": "Carol Bai 多益文法 Part 5#Day21-Q55", "src": "Carol Bai 多益文法 Part 5", "no": "Day21-Q55", "q": "The marketing team needs to finalize the campaign strategy ______ the budget meeting.", "opts": ["unlike", "without", "before", "within"], "ans": 2, "exp": "在預算會議「之前」敲定策略，用 before。", "tags": ["介系詞", "before"]}, {"id": "Carol Bai 多益文法 Part 5#Day26-Q84", "src": "Carol Bai 多益文法 Part 5", "no": "Day26-Q84", "q": "Please be advised that the office will be closed ______ the weekend for renovations.", "opts": ["under", "alongside", "about", "during"], "ans": 3, "exp": "during + 期間名詞 the weekend，表「在…期間」。", "tags": ["介系詞", "during"]}, {"id": "Carol Bai 多益文法 Part 5#Day31-Q13", "src": "Carol Bai 多益文法 Part 5", "no": "Day31-Q13", "q": "Please submit your expense reports ______ attending the company training seminar.", "opts": ["although", "underneath", "after", "throughout"], "ans": 2, "exp": "after + V-ing，表「在…之後」after attending。", "tags": ["介系詞", "after"]}, {"id": "Carol Bai 多益文法 Part 5#Day35-Q32", "src": "Carol Bai 多益文法 Part 5", "no": "Day35-Q32", "q": "The seminar will be targeted ______ improving leadership skills for middle and upper management.", "opts": ["for", "in", "at", "with"], "ans": 2, "exp": "be targeted at「以…為目標、針對」。", "tags": ["介系詞", "at"]}, {"id": "Carol Bai 多益文法 Part 5#Day39-Q8", "src": "Carol Bai 多益文法 Part 5", "no": "Day39-Q8", "q": "______ the shipment was delayed, the team completed the project on time.", "opts": ["Even though", "Instead of", "In addition to", "On top of"], "ans": 0, "exp": "後接完整子句表讓步「儘管」，用連接詞 Even though；其餘後接名詞。", "tags": ["連接詞", "even though"]}, {"id": "Carol Bai 多益文法 Part 5#Day43-Q26", "src": "Carol Bai 多益文法 Part 5", "no": "Day43-Q26", "q": "The company's new policy allows employees to work from home ______ come to the office.", "opts": ["and", "or", "with", "since"], "ans": 1, "exp": "在家或到辦公室，二擇一用對等連接詞 or。", "tags": ["連接詞", "or"]}, {"id": "Carol Bai 多益文法 Part 5#Day45-Q36", "src": "Carol Bai 多益文法 Part 5", "no": "Day45-Q36", "q": "ABC Consulting Firm provides a 5 percent discount ______ clients complete their payment within 15 days.", "opts": ["also", "but", "if", "yet"], "ans": 2, "exp": "條件句「如果…就給折扣」，用連接詞 if。", "tags": ["連接詞", "if"]}, {"id": "Carol Bai 多益文法 Part 5#Day46-Q43", "src": "Carol Bai 多益文法 Part 5", "no": "Day46-Q43", "q": "______ the necessary permits are obtained, the construction project cannot commence.", "opts": ["Mostly", "At least", "No more", "Unless"], "ans": 3, "exp": "unless「除非」引導條件，除非取得許可否則不能動工。", "tags": ["連接詞", "unless"]}, {"id": "Carol Bai 多益文法 Part 5#Extra-Q1", "src": "Carol Bai 多益文法 Part 5", "no": "Extra-Q1", "q": "The marketing team ______ a new strategy to increase brand awareness last quarter.", "opts": ["develop", "developed", "was developing", "develops"], "ans": 1, "exp": "last quarter 為明確過去時間，用過去簡單式 developed。", "tags": ["時態", "過去式"]}, {"id": "Carol Bai 多益文法 Part 5#Extra-Q2", "src": "Carol Bai 多益文法 Part 5", "no": "Extra-Q2", "q": "The annual report ______ by the accounting department before the board meeting.", "opts": ["prepare", "prepared", "was prepared", "prepares"], "ans": 2, "exp": "報告是「被」準備的，用被動語態；配合過去時間用 was prepared。", "tags": ["語態", "被動"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C6-Day7-Q3", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C6-Day7-Q3", "q": "Ms. Garcia will set ______ on her business trip to Singapore early tomorrow morning.", "opts": ["up", "out", "aside", "off"], "ans": 3, "exp": "set off「出發、動身」；set up 設立、set aside 撥出、set out 著手（也可指出發，但搭配 on a trip 慣用 set off）。", "tags": ["片語動詞", "set"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C6-Day8-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C6-Day8-Q1", "q": "At the sales meeting, the manager urged the team to go ______ the biggest contract.", "opts": ["over", "for", "with", "through"], "ans": 1, "exp": "go for「爭取、努力追求」；go over 檢查、go through 經歷、go with 搭配。", "tags": ["片語動詞", "go"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C6-Day8-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C6-Day8-Q2", "q": "The legal team must go ______ every clause of the contract carefully before the CEO signs it.", "opts": ["over", "for", "with", "through"], "ans": 0, "exp": "go over「仔細檢查、逐一審視」每個條款。", "tags": ["片語動詞", "go"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day1-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day1-Q1", "q": "The contract was signed ______ both parties after the negotiation.", "opts": ["for", "with", "by", "on"], "ans": 2, "exp": "被動語態 be signed by sb，表「由…簽署」。", "tags": ["字彙", "介系詞"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day1-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day1-Q2", "q": "The new policy will be implemented ______ departments starting next month.", "opts": ["to", "by", "on", "across"], "ans": 3, "exp": "across departments「跨各部門」，表遍及範圍。", "tags": ["字彙", "介系詞"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day1-Q3", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day1-Q3", "q": "The CEO expressed gratitude ______ the employees for their hard work.", "opts": ["to", "with", "on", "by"], "ans": 0, "exp": "express gratitude to sb「向某人表達感謝」。", "tags": ["字彙", "介系詞"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day2-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day2-Q1", "q": "The manager was impressed with her resume and decided to schedule ______ immediately.", "opts": ["a resume", "an interview", "an offer", "a contract"], "ans": 1, "exp": "對履歷印象深刻，接著安排「面試」an interview。", "tags": ["字彙", "徵才"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day4-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day4-Q1", "q": "Our company will launch a new advertising ______ next month to promote our products.", "opts": ["campaign", "survey", "advertisement", "brochure"], "ans": 0, "exp": "advertising campaign「廣告活動」為固定搭配。", "tags": ["字彙", "行銷"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day5-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day5-Q1", "q": "You should make a hotel ______ at least two weeks before your business trip.", "opts": ["reservation", "confirmation", "expense", "itinerary"], "ans": 0, "exp": "make a reservation「預訂」，hotel reservation 訂房。", "tags": ["字彙", "商旅"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day6-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day6-Q1", "q": "You can use your credit card to make ______ on our secure website.", "opts": ["a purchase", "a refund", "a receipt", "a coupon"], "ans": 0, "exp": "make a purchase「進行購買」。", "tags": ["字彙", "購物"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day7-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day7-Q1", "q": "Before heading to the airport, it is important to confirm your ______ online.", "opts": ["flight", "boarding pass", "baggage", "destination"], "ans": 0, "exp": "出發前線上「確認航班」confirm your flight（線上報到）。", "tags": ["字彙", "商旅"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day8-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day8-Q1", "q": "The finance department is working hard to prepare the annual ______ for the next fiscal year.", "opts": ["budget", "expense", "fund", "investment"], "ans": 0, "exp": "annual budget「年度預算」。", "tags": ["字彙", "財務"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day10-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day10-Q1", "q": "To enter the new market, our team must develop an effective ______.", "opts": ["strategy", "objective", "resource", "progress"], "ans": 0, "exp": "develop a strategy「制定策略」。", "tags": ["字彙", "商業"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day10-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day10-Q2", "q": "With this new plan, we hope to achieve our main ______ of increasing market share.", "opts": ["strategy", "objective", "resource", "progress"], "ans": 1, "exp": "objective「目標」，achieve an objective 達成目標。", "tags": ["字彙", "商業"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day11-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day11-Q1", "q": "Both parties must sign the ______ before the agreement is official.", "opts": ["lease", "property", "facility", "location"], "ans": 0, "exp": "sign the lease「簽署租約」；property/facility/location 均非可簽署文件。", "tags": ["字彙", "租賃"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day12-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day12-Q1", "q": "The management has decided to implement a new ______ regarding work-from-home arrangements.", "opts": ["policy", "guideline", "regulation", "schedule"], "ans": 0, "exp": "implement a new policy「實施新政策」，管理層針對制度多用 policy。", "tags": ["字彙", "管理"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day13-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day13-Q1", "q": "After reviewing over 100 applications, we will shortlist the top five ______ for an interview.", "opts": ["candidate", "qualification", "reference", "experience"], "ans": 0, "exp": "候選人 candidate；shortlist candidates 列入面試名單。", "tags": ["字彙", "徵才"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day14-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day14-Q1", "q": "For popular restaurants, it is always a good idea to book ______ in advance.", "opts": ["a table", "a special", "an order", "a check"], "ans": 0, "exp": "book a table「訂位」。", "tags": ["字彙", "餐飲"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day15-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day15-Q1", "q": "To ensure the meeting is productive, we must set a clear ______ beforehand.", "opts": ["agenda", "venue", "registration", "schedule"], "ans": 0, "exp": "agenda「議程」，set an agenda 訂定會議議程。", "tags": ["字彙", "會議"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day16-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day16-Q1", "q": "To better manage his finances, Mr. Smith decided to open a new savings ______ at the local bank.", "opts": ["account", "loan", "deposit", "transaction"], "ans": 0, "exp": "savings account「儲蓄帳戶」，open an account 開戶。", "tags": ["字彙", "財務"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day19-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day19-Q1", "q": "The museum is proud to display its newest ______: a restored 18th-century carriage.", "opts": ["exhibit", "admission", "artifact", "collection"], "ans": 0, "exp": "博物館展出的「展品」用 exhibit；admission 是入場費。", "tags": ["字彙", "藝文"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day21-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day21-Q1", "q": "The receptionist helped me schedule ______ for my next dental check-up in six months.", "opts": ["an appointment", "a cavity", "an X-ray", "a cleaning"], "ans": 0, "exp": "schedule an appointment「預約」。", "tags": ["字彙", "醫療"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day22-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day22-Q2", "q": "Since neither side would agree completely, they decided to reach ______ by meeting in the middle.", "opts": ["a deal", "a compromise", "terms", "a counteroffer"], "ans": 1, "exp": "reach a compromise「達成妥協」，各退一步。", "tags": ["字彙", "談判"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day24-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day24-Q1", "q": "Before submitting the report, please edit the ______ carefully to check for any spelling errors.", "opts": ["document", "file", "copy", "text"], "ans": 0, "exp": "edit the document「編修文件」，校對拼字錯誤。", "tags": ["字彙", "文書"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day32-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day32-Q1", "q": "Before mass production, the R&D team must first develop a functional ______ for testing.", "opts": ["prototype", "feedback", "requirement", "product"], "ans": 0, "exp": "prototype「原型、雛型」，量產前先做原型測試。", "tags": ["字彙", "研發"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day35-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day35-Q1", "q": "The machine stopped working, so we had to call a specialist to replace a faulty electronic ______.", "opts": ["component", "malfunction", "manual", "technician"], "ans": 0, "exp": "electronic component「電子零件」，更換故障零件。", "tags": ["字彙", "技術"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day37-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day37-Q1", "q": "Because of her outstanding performance, Ms. Lin expects to receive ______ at the end of the year.", "opts": ["a raise", "benefits", "a deduction", "a pension"], "ans": 0, "exp": "a raise「加薪」，表現優異年底期待加薪。", "tags": ["字彙", "職場"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day43-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day43-Q1", "q": "All citizens are required to declare their annual ______ to the tax authorities.", "opts": ["income", "refund", "deadline", "audit"], "ans": 0, "exp": "declare income「申報收入」。", "tags": ["字彙", "稅務"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day43-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day43-Q2", "q": "If you have overpaid your taxes, you will be eligible to receive ______ from the government.", "opts": ["an income", "a refund", "a deadline", "an audit"], "ans": 1, "exp": "溢繳稅款可獲「退稅」a refund。", "tags": ["字彙", "稅務"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day44-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day44-Q1", "q": "To develop a successful business plan, a new company must first identify its main ______.", "opts": ["competitor", "market share", "weakness", "trend"], "ans": 0, "exp": "identify its main competitor「找出主要競爭對手」。", "tags": ["字彙", "商業"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day45-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day45-Q2", "q": "If the supplier is not willing to lower the ______, we will have to consider other options.", "opts": ["discount", "price", "budget", "offer"], "ans": 1, "exp": "lower the price「降價」，供應商不肯降價就另尋選擇。", "tags": ["字彙", "採購"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day46-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day46-Q1", "q": "To give customers peace of mind, all our electronic devices offer a two-year limited ______.", "opts": ["warranty", "return", "exchange", "checkout"], "ans": 0, "exp": "warranty「保固」，two-year limited warranty 兩年有限保固。", "tags": ["字彙", "售後"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day49-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day49-Q2", "q": "Every salesperson is expected to meet their monthly sales ______ to be eligible for a bonus.", "opts": ["figures", "quota", "pitch", "commission"], "ans": 1, "exp": "sales quota「銷售配額、業績目標」，達標才能領獎金。", "tags": ["字彙", "業務"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day50-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day50-Q2", "q": "Due to a critical safety concern, the plant manager made the decision to halt ______ immediately.", "opts": ["component", "production", "assembly line", "output"], "ans": 1, "exp": "halt production「停止生產」。", "tags": ["字彙", "製造"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day51-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day51-Q1", "q": "The legal department has been asked to draft a new employment ______ for all incoming staff.", "opts": ["contract", "obligation", "clause", "agreement"], "ans": 0, "exp": "employment contract「僱傭合約」，draft a contract 擬合約。", "tags": ["字彙", "法務"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day51-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day51-Q2", "q": "Both parties are legally bound to fulfill their ______ as stated in the signed document.", "opts": ["contract", "obligation", "clause", "agreement"], "ans": 1, "exp": "fulfill their obligations「履行義務」。", "tags": ["字彙", "法務"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day52-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day52-Q1", "q": "Our accounting department will issue ______ to the customer as soon as the order is shipped.", "opts": ["an invoice", "an account", "a fee", "a charge"], "ans": 0, "exp": "issue an invoice「開立發票／帳單」。", "tags": ["字彙", "財務"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day52-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day52-Q2", "q": "We kindly request that you settle your outstanding ______ by the end of the month.", "opts": ["invoice", "account", "fee", "charge"], "ans": 1, "exp": "settle your account「結清帳款」，outstanding account 未結帳款。", "tags": ["字彙", "財務"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day54-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day54-Q1", "q": "I need to go online to book ______ for my business trip to Singapore next month.", "opts": ["a flight", "a seat", "a fare", "an itinerary"], "ans": 0, "exp": "book a flight「訂機票」。", "tags": ["字彙", "商旅"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day54-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day54-Q2", "q": "After confirming your booking, you will be prompted to select your preferred ______ on the aircraft.", "opts": ["flight", "seat", "fare", "itinerary"], "ans": 1, "exp": "select your preferred seat「選擇偏好座位」。", "tags": ["字彙", "商旅"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day55-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day55-Q1", "q": "To begin our meal, we decided to order a fresh salad as ______.", "opts": ["an appetizer", "a main course", "a beverage", "an ingredient"], "ans": 0, "exp": "appetizer「開胃菜、前菜」，用來開場。", "tags": ["字彙", "餐飲"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day55-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day55-Q2", "q": "For your ______, you can choose either the grilled salmon or the roasted chicken.", "opts": ["appetizer", "main course", "beverage", "ingredient"], "ans": 1, "exp": "主餐 main course，鮭魚或雞肉二選一。", "tags": ["字彙", "餐飲"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day56-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day56-Q1", "q": "The administrative assistant's first task each morning is to sort the incoming ______.", "opts": ["mail", "document", "file", "message"], "ans": 0, "exp": "incoming mail「進來的信件」，整理郵件。", "tags": ["字彙", "辦公室"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day56-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day56-Q2", "q": "For security reasons, you must shred any ______ that contains sensitive company information.", "opts": ["mail", "document", "file", "message"], "ans": 1, "exp": "shred a document「碎掉文件」，銷毀含機密資訊的文件。", "tags": ["字彙", "辦公室"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day57-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day57-Q1", "q": "Before you attempt to purchase, it is best to check the ______ of the seats online.", "opts": ["availability", "booking", "voucher", "barcode"], "ans": 0, "exp": "check the availability「查看有無空位」。", "tags": ["字彙", "購票"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day57-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day57-Q2", "q": "You will receive an email shortly to confirm your ______ for the concert.", "opts": ["availability", "booking", "voucher", "barcode"], "ans": 1, "exp": "confirm your booking「確認訂位／訂票」。", "tags": ["字彙", "購票"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day58-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day58-Q1", "q": "The popular rock band has announced that they will release their new ______ this fall.", "opts": ["album", "instrument", "melody", "orchestra"], "ans": 0, "exp": "release an album「發行專輯」。", "tags": ["字彙", "音樂"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day58-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day58-Q2", "q": "She is a gifted musician who can play several different types of musical ______.", "opts": ["album", "instrument", "melody", "orchestra"], "ans": 1, "exp": "musical instrument「樂器」。", "tags": ["字彙", "音樂"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day59-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day59-Q2", "q": "Due to the original film's huge success, the studio decided to direct ______.", "opts": ["an actor", "a sequel", "a blockbuster", "an award"], "ans": 1, "exp": "sequel「續集」，原片成功後拍續集。", "tags": ["字彙", "影視"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day60-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day60-Q1", "q": "If you are feeling unwell, you have the right to take a sick ______.", "opts": ["leave", "absence", "time clock", "timesheet"], "ans": 0, "exp": "sick leave「病假」，take a sick leave 請病假。", "tags": ["字彙", "職場"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day61-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day61-Q1", "q": "The event planner will call a meeting tomorrow to finalize the ______ for the three-day workshop.", "opts": ["schedule", "transportation", "accommodation", "details"], "ans": 0, "exp": "finalize the schedule「敲定議程／時程」。", "tags": ["字彙", "活動"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day65-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day65-Q2", "q": "The manager will ______ a memo to inform all employees about the new company policy.", "opts": ["organize", "circulate", "handle", "approve"], "ans": 1, "exp": "circulate a memo「發布、傳閱通知」。", "tags": ["字彙", "辦公室"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day66-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day66-Q1", "q": "This new advertising campaign is specifically designed to ______ a younger audience.", "opts": ["target", "promote", "generate", "measure"], "ans": 0, "exp": "target an audience「鎖定客群」。", "tags": ["字彙", "行銷"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day66-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day66-Q2", "q": "The company plans to use social media influencers to ______ its new line of clothing.", "opts": ["target", "promote", "generate", "measure"], "ans": 1, "exp": "promote「推廣、宣傳」新產品線。", "tags": ["字彙", "行銷"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day67-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day67-Q1", "q": "After graduating, they decided to ______ on a journey through Southeast Asia.", "opts": ["embark", "explore", "extend", "cancel"], "ans": 0, "exp": "embark on「展開、著手」，embark on a journey 踏上旅程。", "tags": ["字彙", "動詞"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day67-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day67-Q2", "q": "The best way to get to know a new place is to ______ the city and visit its local markets.", "opts": ["embark", "explore", "extend", "cancel"], "ans": 1, "exp": "explore the city「探索城市」。", "tags": ["字彙", "動詞"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day68-Q1", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day68-Q1", "q": "I wasn't looking for anything specific; I was ______ through the bookstore for an hour.", "opts": ["browsing", "purchasing", "redeeming", "comparing"], "ans": 0, "exp": "browse「隨意瀏覽」，沒有特定目標地逛。", "tags": ["字彙", "動詞"]}, {"id": "Carol Bai 多益 Part 5 字彙片語#C7-Day68-Q2", "src": "Carol Bai 多益 Part 5 字彙片語", "no": "C7-Day68-Q2", "q": "Once you are ready to ______ an item, please proceed to the checkout counter.", "opts": ["browse", "purchase", "redeem", "compare"], "ans": 1, "exp": "purchase「購買」，準備結帳。", "tags": ["字彙", "動詞"]}, {"id": "國學閱讀綠本 第一回合#Q106", "src": "國學閱讀綠本 第一回合", "no": "Q106", "q": "______ workers find in the concert hall will remain in the lost and found center for only one week.", "opts": ["Few", "Several", "Anything", "Most"], "ans": 2, "exp": "句意是在【音樂廳發現的任何東西，只會在失物招領中心保留一周】，所以答案是不定代名詞(C) Anything(任何東西)。代名詞(A)、(B)、(D)分別表示【(許多東西中的)少數/幾個/大部分】，不符合句子要表達的意思。", "tags": ["代名詞", "不定代名詞"]}, {"id": "國學閱讀綠本 第一回合#Q118", "src": "國學閱讀綠本 第一回合", "no": "Q118", "q": "The company shifted ______ from its old business model to a fully digital one.", "opts": ["radicalizing", "radically", "radicalize", "radical"], "ans": 1, "exp": "只有副詞能修飾空格前面的動詞(shifted)，所以答案是副詞(B) radically (激進地)。現在分詞(A)，動詞(C)、名詞或形容詞(D)不能修飾動詞。", "tags": ["詞性", "副詞"]}, {"id": "國學閱讀綠本 第一回合#Q125", "src": "國學閱讀綠本 第一回合", "no": "Q125", "q": "Member of the loyalty program may take advantage of discount offers ______ earn points for their purchases.", "opts": ["in case", "so that", "regarding", "as well as"], "ans": 3, "exp": "可以將助動詞 (may) 後面的動詞原型 (take advantage of )和動詞原型 (earn) 對等連接，而且能表示【會員除了獲得購物的點數以外，也可以利用折扣優惠】的是B as well as A (除了A還有B)，所以相關連接詞(D) as well as 是正確答案。副詞子句連接詞(A)和(B)後面要接有主詞和動詞的子句，但空格後面缺少主詞，所以這兩個選項不會是正確答案。介系詞(C)後面要接名詞。", "tags": ["連接詞", "as well as"]}, {"id": "國學閱讀綠本 第一回合#Q127", "src": "國學閱讀綠本 第一回合", "no": "Q127", "q": "______ all the cities that the pop singer visited during her recent world tour, Seoul was her favorite.", "opts": ["Of", "About", "To", "Upon"], "ans": 0, "exp": "句意是在造訪所有城市中，首爾是她的最愛，所以介系詞(A) Of (...之中的) 是正確答案。(B) About 表示【關於...】。(C) To 表示方向【往...】。(D) Upon 表示位置或時間點 【在...之上，...之後】", "tags": ["介系詞", "Of"]}, {"id": "國學閱讀綠本 第二回合#Q101", "src": "國學閱讀綠本 第二回合", "no": "Q101", "q": "The interns will work ______ the direction of the research department manager.", "opts": ["beyond", "among", "under", "beside"], "ans": 2, "exp": "句意是「實習生將在研究部門經理的指導下工作」，主要考驗介系詞的慣用搭配。在英文中，「under the direction of...」是一個非常常見的固定片語，意思是「在⋯⋯的指導、監督或管理之下」，這裡的 under 帶有從屬或受某人領導的語意。選項 (A) beyond（超越）、(B) among（在⋯⋯之中）以及 (D) beside（在⋯⋯旁邊）在語意邏輯上都無法與 direction（指導）搭配來表示職場上的管理或帶領關係，因此 (C) 是最符合句意與文法的唯一選擇。", "tags": ["介系詞"]}, {"id": "國學閱讀綠本 第二回合#Q103", "src": "國學閱讀綠本 第二回合", "no": "Q103", "q": "The directors of PenTex are meeting with executives from DRW Corporation, which ______ have talked about merging with.", "opts": ["them", "themselves", "their", "they"], "ans": 3, "exp": "句意是「PenTex 的董事們正與 DRW 公司的各高層主管開會，他們曾經討論過要與該公司合併。」在這個句子中，逗號後面的 \"which ______ have talked about merging with\" 是一個非限定關係子句，當中的 which 作為關係代名詞，代替前面提到的 DRW Corporation。而在這個關係子句裡，\"have talked\" 是動詞片語，因此空格處需要填入一個主格代名詞來作為子句的主詞。根據上下文邏輯，討論合併的主體是前面提過的「PenTex 的董事們（The directors）」，因為是複數名詞，所以必須使用複數的主格代名詞(D) they 來代替。選項 (A) them 是受格，(B) themselves 是反身代名詞，(C) their 是所有格，這三者在文法上都不能直接放在動詞前當作主詞。", "tags": ["代名詞"]}, {"id": "國學閱讀綠本 第二回合#Q109", "src": "國學閱讀綠本 第二回合", "no": "Q109", "q": "Arrow Publicity produced a campaign that is designed to ______ audiences between the ages of 18 and 25.", "opts": ["appeal to", "approve of", "point out", "result from"], "ans": 0, "exp": "句意是「Arrow 宣傳公司製作了一個旨在吸引 18 到 25 歲之間受眾的行銷活動。」本題主要測驗動詞與介系詞搭配的片語語意。選項 (A) appeal to 的意思是「吸引、引起⋯⋯的興趣」，放在這裡與後方的受詞「受眾（audiences）」搭配，非常符合行銷活動（campaign）的目的與商業邏輯。選項 (B) approve of 意思是「贊成、同意」，(C) point out 是「指出」，(D) result from 則是「起因於」，這三個選項填入空格後在語意上都顯得突兀，無法合理串聯前後文，因此 (A) 是唯一正確的選擇。", "tags": ["動詞片語"]}, {"id": "國學閱讀綠本 第二回合#Q110", "src": "國學閱讀綠本 第二回合", "no": "Q110", "q": "The company will provide training to new recruits, so neither experience ______ a degree is required.", "opts": ["and", "but", "nor", "or"], "ans": 2, "exp": "句意是「公司將會為新進員工提供培訓，因此既不需要經驗也不需要學位。」這題主要考驗相關連接詞（correlative conjunctions）的固定搭配用法。在英文文法中，「neither... nor...」是一個絕對的成對連接詞片語，用來同時否定兩個選項，表示「既不⋯⋯也不⋯⋯」。既然題目句中已經出現了 \"neither\"，空格處就必定要填入 (C) nor 來對等連接 \"experience\"（經驗）與 \"a degree\"（學位）這兩個名詞。選項 (D) or 必須與 either 搭配使用（either... or... 表示「不是⋯⋯就是⋯⋯」），而 (A) and（常搭配 both）與 (B) but（常搭配 not only）在語法結構上都無法與 neither 搭配。", "tags": ["連接詞"]}, {"id": "國學閱讀綠本 第二回合#Q112", "src": "國學閱讀綠本 第二回合", "no": "Q112", "q": "Employees will now be offered the ______ of working from home for up to half of their weekly hours.", "opts": ["benefit", "benefited", "beneficial", "benefiting"], "ans": 0, "exp": "句意是「員工現在將享有每週最多一半工時可以居家辦公的福利。」在這題的文法結構中，空格前出現了定冠詞 \"the\"，且其後方緊跟著由介系詞 \"of\" 引導的修飾片語，這明確標示著空格處必須填入一個名詞來作為句中被賦予的事物（保留受詞）。選項 (A) benefit 在此作為名詞，意思是「好處、福利」，完美符合句法結構與職場語意。選項 (B) benefited 是動詞的過去式或過去分詞，(C) beneficial 是形容詞（有益的），(D) benefiting 是動詞現在分詞，這三者的詞性都無法直接放在定冠詞 \"the\" 之後作為獨立名詞使用，因此 (A) 是唯一正確的選擇。", "tags": ["名詞"]}, {"id": "國學閱讀綠本 第二回合#Q113", "src": "國學閱讀綠本 第二回合", "no": "Q113", "q": "Knoll Consulting tries to hire staff ______ personal values match the company's.", "opts": ["whom", "which", "whose", "who"], "ans": 2, "exp": "句意是「Knoll 顧問公司試圖聘用個人價值觀與公司相符的員工。」這題主要測驗關係代名詞中「所有格」的用法。在句子中，空格前方的先行詞是 \"staff\"（員工），而空格後方緊接著的是名詞 \"personal values\"（個人價值觀）。這裡要表達的邏輯是「『員工的』個人價值觀」，兩者之間存在著所有權的關係，因此必須填入所有格關係代名詞 whose 來連接兩個子句並修飾前面的 staff。選項 (A) whom 是受格，(B) which 用來指稱事物，(D) who 則是主格，這三個選項都無法表現出「某人的⋯⋯」這種所屬關係，因此 (C) 是唯一正確的選擇。", "tags": ["關係代名詞"]}, {"id": "國學閱讀綠本 第二回合#Q117", "src": "國學閱讀綠本 第二回合", "no": "Q117", "q": "Housing costs in New York are far higher than ______ in its neighboring state, New Jersey.", "opts": ["anyone", "other", "that", "those"], "ans": 3, "exp": "句意是「紐約的住房成本遠高於其鄰州紐澤西州」，考驗的是英文比較句型中指示代名詞的用法。為了在同一個句子裡避免重複提及相同的名詞，英文通常會使用代名詞來代替前面已經出現過的事物。在這題當中，比較的對象是兩地的「住房成本（Housing costs）」，因為題幹的 costs 是一個複數名詞，所以空格處必須填入對應的複數代名詞 those 來代替紐澤西州的住房成本。如果今天題目使用的是單數型態（例如 cost），才會選擇 (C) 的 that；至於選項 (A) 的 anyone（任何人）在語意上完全不通，而選項 (B) 的 other 在文法上無法單獨在此作為代名詞進行比較。", "tags": ["指示代名詞"]}, {"id": "國學閱讀綠本 第二回合#Q120", "src": "國學閱讀綠本 第二回合", "no": "Q120", "q": "Having made a reservation, Mr. Quinn and his colleagues were seated immediately ______ arriving at the restaurant.", "opts": ["up", "in", "upon", "to"], "ans": 2, "exp": "句意是「由於已經預先訂位，Quinn 先生和他的同事們一抵達餐廳就被立刻安排入座」。這裡考驗的是介系詞的慣用語法。在英文中，「upon + 動名詞 (V-ing)」（或用 on + 動名詞）是一個常見的句型，用來表達「一……就……」或是「在發生某事的當下」的意思。在這個句子裡，「immediately upon arriving」精準地表達了他們抵達的瞬間就隨即入座的狀態。其他的選項 (A) up、(B) in 與 (D) to 在這裡皆無法與 arriving 搭配出表示時間緊接發生的邏輯關聯，因此 (C) 是唯一符合文法與句意的正確解答。", "tags": ["介系詞"]}, {"id": "國學閱讀綠本 第二回合#Q122", "src": "國學閱讀綠本 第二回合", "no": "Q122", "q": "During her first year as editor-in-chief, Ms. Reed expanded The National Gazette's ______ to over 250,000.", "opts": ["Read", "Readers", "reading", "readership"], "ans": 3, "exp": "句意是「在 Reed 女士擔任總編輯的第一年，她將《國家公報》的讀者人數（或讀者群）擴增至超過 25 萬人」，主要考驗的是字彙語意與詞性的搭配。空格前有所有格「The National Gazette's」，因此後面必須接上名詞。雖然選項 (B) 的 readers（讀者們）也是名詞，但在英文慣用語法中，要表達一份刊物的「總讀者人數」或「讀者群」時，會使用集合名詞 readership。搭配動詞 expand（擴大、擴增）與具體達到的數量「250,000」時，使用 expand the readership（擴大讀者群）是最符合新聞出版界的道地表達方式（如果用 readers，通常會寫成 increased the number of readers）。至於選項 (A) read 通常作動詞使用，而 (C) reading 則是表示「閱讀」這個動作的動名詞，兩者在語意與詞性上皆無法用來表示可被量化的受眾規模。", "tags": ["名詞"]}, {"id": "國學閱讀綠本 第二回合#Q125", "src": "國學閱讀綠本 第二回合", "no": "Q125", "q": "The e-mail sent by Mr. Duchene at Laudner Holdings is ______ Ms. Coleman was waiting for.", "opts": ["who", "what", "how", "when"], "ans": 1, "exp": "句意是「Laudner 控股公司的 Duchene 先生所寄來的那封電子郵件，正是 Coleman 女士一直在等的東西。」在這個句子中，be 動詞 \"is\" 的後面需要一個名詞性的結構來作為主詞補語，同時後方 \"waiting for\" 的介系詞 \"for\" 也缺少了受詞。選項 (B) what 作為複合關係代名詞，本身就隱含了先行詞，其功能等同於 \"the thing that\"（那個事物），填入後所形成的 \"what Ms. Coleman was waiting for\" 完美解決了前後兩端的文法需求。選項 (A) who 用來指稱人，(C) how 指的是方式，(D) when 則是指時間，這三者在語意上都無法用來代指前面提到的「電子郵件（the e-mail）」。", "tags": ["關係代名詞"]}, {"id": "國學閱讀綠本 第三回合#Q103", "src": "國學閱讀綠本 第三回合", "no": "Q103", "q": "Ms. Conner did not win the Employee of the Year Award because a colleague's sales record was better than ______.", "opts": ["hers", "herself", "her", "she"], "ans": 0, "exp": "句意是「Conner 沒有贏得年度最佳員工獎，因為一位同事的銷售紀錄比她的還要好。」這題測驗的是比較級結構中的「平行對稱」原則。在 \"better than\" 的前後，比較的對象必須一致：前面是 \"a colleague's sales record\"（同事的銷售紀錄），後面也必須是「她的銷售紀錄」。為了避免重複寫出 \"sales record\"，這裡必須使用所有格代名詞 (A) hers，它就等於 \"her sales record\"。其他選項的詞性皆不符：(B) herself 為反身代名詞；(C) her 若作所有格必須緊接名詞；(D) she 為主格。", "tags": ["代名詞"]}, {"id": "國學閱讀綠本 第三回合#Q108", "src": "國學閱讀綠本 第三回合", "no": "Q108", "q": "A photography exhibition entitled The Awakening is currently ______ in the Pulsen Gallery's main hall.", "opts": ["expressed", "transformed", "displayed", "reflected"], "ans": 2, "exp": "句意是「一場名為《覺醒》的攝影展目前正在 Pulsen 藝廊的大廳展出。」這題測驗的是動詞單字在被動語態中的語意搭配。主詞是「攝影展 (photography exhibition)」，配合藝廊 (gallery) 的情境，最符合邏輯的動作是「被展出」。因此，填入 (C) displayed 形成 \"is currently displayed\"（目前正被展出）是唯一正確的選擇。其他選項：(A) expressed（被表達）、(B) transformed（被轉換）、(D) reflected（被反映／反射），在語意上都無法與攝影展合理搭配。", "tags": ["字彙", "語態"]}, {"id": "國學閱讀綠本 第三回合#Q109", "src": "國學閱讀綠本 第三回合", "no": "Q109", "q": "The municipal government has promised that it will take ______ to reduce downtown traffic.", "opts": ["acting", "action", "activation", "activists"], "ans": 1, "exp": "句意是「市政府已承諾將採取行動來減少市中心的交通流量。」這題測驗的是名詞的慣用搭配（collocation）。「採取行動」在英文中的固定用法是 take action，此處的 action 作為不可數名詞使用，前面不加冠詞。其他選項：(A) acting 是動名詞或指「演戲、表演」，無法與 take 搭配成「採取行動」；(C) activation 意為「啟動、活化」，多用於機器或系統的啟用，語意不符；(D) activists 指「（社會運動）行動主義者、激進份子」，是指人的可數名詞，填入後語意變成「政府會帶走激進份子」，不合邏輯。", "tags": ["名詞", "固定搭配"]}, {"id": "國學閱讀綠本 第三回合#Q110", "src": "國學閱讀綠本 第三回合", "no": "Q110", "q": "Soft drink manufacturer Fizz Life ______ a backlash from customers after changing its recipe for Ricochet Cola last year.", "opts": ["was faced", "has been faced", "faced", "to face"], "ans": 2, "exp": "句意是「軟性飲料製造商 Fizz Life 去年更改 Ricochet 可樂的配方後，遭到了顧客的強烈反彈。」這題同時測驗語態與時態。空格後方有受詞「a backlash」（反彈、抵制），表示動詞 face（面對、遭遇）在此是及物動詞的主動用法，主詞 Fizz Life 是動作的執行者，因此不能用被動語態；再加上句尾的時間副詞「last year」（去年）標示動作已完成於過去的特定時間點，必須用過去簡單式，所以 (C) faced 是正確答案。選項 (A) was faced 與 (B) has been faced 都是被動語態，後面若要接「反彈」必須寫成 be faced **with** a backlash（此處沒有 with，且句子已有受詞，故不合）；(B) 的現在完成式也與明確的過去時間 last year 衝突。選項 (D) to face 是不定詞，本句缺的是主要動詞，不定詞無法單獨擔任主要動詞。", "tags": ["語態", "時態"]}, {"id": "國學閱讀綠本 第三回合#Q111", "src": "國學閱讀綠本 第三回合", "no": "Q111", "q": "As a branch manager, Mr. Finley finds resolving staff conflicts ______ of his duties.", "opts": ["difficult", "more difficult", "the most difficult", "difficultly"], "ans": 2, "exp": "句意是「身為分店經理，Finley 先生認為排解員工之間的衝突是他所有職責中最困難的一項。」這題測驗形容詞的級數。句型是 find + 受詞 + 受詞補語（find A B，覺得 A 是 B），空格要填形容詞當補語；關鍵線索是空格後方的「of his duties」（在他的職責當中），表示是在一個群體（三者以上）之中做比較，這正是最高級的使用時機，且最高級前面必須加定冠詞 the，因此 (C) the most difficult 完全符合。選項 (A) difficult 是原級，無法表達「當中最⋯⋯」的比較語意；(B) more difficult 是比較級，只能用於兩者相比且通常搭配 than；(D) difficultly 是副詞，不能當受詞補語修飾前面的動名詞片語。", "tags": ["比較級", "最高級"]}, {"id": "國學閱讀綠本 第三回合#Q112", "src": "國學閱讀綠本 第三回合", "no": "Q112", "q": "The dinner plates and utensils manufactured by Tessio are suitable for any ______.", "opts": ["leisure", "occasion", "performance", "effect"], "ans": 1, "exp": "句意是「Tessio 所生產的餐盤與餐具適用於任何場合。」這題測驗名詞的字彙語意與慣用搭配。空格前是 any，後面要接一個能與「餐盤、餐具」的使用情境合理搭配的名詞；(B) occasion 意為「場合、時機」，「suitable for any occasion」（適合任何場合）是描述商品用途時極常見的固定說法，無論是日常用餐或正式宴會都適用，語意最通順。選項 (A) leisure 指「閒暇、休閒時間」，是抽象的時間概念，不能用來指稱使用餐具的場合；(C) performance 指「表演、績效表現」；(D) effect 指「效果、影響」，這兩者與餐具的適用情境完全搭不上，因此 (B) 是唯一正確的答案。", "tags": ["字彙", "名詞"]}, {"id": "國學閱讀綠本 第三回合#Q115", "src": "國學閱讀綠本 第三回合", "no": "Q115", "q": "The manager decided to provide the employees with additional training, ______ their weaknesses.", "opts": ["addressing", "addressed", "address", "addresses"], "ans": 0, "exp": "句意是「經理決定為員工提供額外的訓練，以改善（處理）他們的弱點。」這題測驗分詞構句。逗號前面「The manager decided to provide...」已經是一個結構完整的句子（有主詞 The manager、有主要動詞 decided），逗號後方沒有連接詞，所以空格處不能再放一個有時態的動詞，必須改用分詞來引導附屬的分詞構句。判斷用現在分詞還是過去分詞的關鍵在於主動被動：句子隱含的主詞是前面的 the manager／the training，而空格後方還有受詞 \"their weaknesses\"，是「主動去處理弱點」，因此要用現在分詞 (A) addressing。選項 (B) addressed 是過去分詞，表被動且後面不該再帶受詞；(C) address 與 (D) addresses 都是限定動詞，在沒有連接詞的情況下會造成兩個主要動詞並列的錯誤句構。", "tags": ["分詞構句", "現在分詞"]}, {"id": "國學閱讀綠本 第三回合#Q119", "src": "國學閱讀綠本 第三回合", "no": "Q119", "q": "Although Mr. Miller had been given clear directions to the conference venue, he drove right ______ it.", "opts": ["toward", "over", "past", "out"], "ans": 2, "exp": "句意是「儘管 Miller 先生已經拿到前往會議場地的清楚路線指示，他還是開車直接開過（錯過）了會場。」這題測驗介系詞的語意，並注意 Although 帶出的「語意逆轉」：既然前半句說他有清楚的指示，後半句就應該是出乎意料的負面結果，也就是「錯過了地點」。介系詞 (C) past 表示「經過、越過（某個定點）」，drive past it 正是「開車經過它而沒停下」，完全符合這個轉折語意。選項 (A) toward 表示「朝⋯⋯方向」，會變成順利往會場前進，與 Although 的轉折衝突；(B) over 表示「從上方越過」，不符合開車經過地面定點的情境；(D) out 是副詞，後面不能直接接受詞 it（要寫成 drove out of it 才成立）。另外 right 在此是加強語氣的副詞，表示「就這樣直接⋯⋯」，也是 right past 的常見搭配。", "tags": ["介系詞"]}, {"id": "國學閱讀綠本 第三回合#Q121", "src": "國學閱讀綠本 第三回合", "no": "Q121", "q": "New recruits are required to join a training course ______ they have relevant work experience.", "opts": ["in spite of", "even if", "as though", "in case"], "ans": 1, "exp": "句意是「即使新進人員已具備相關工作經驗，還是必須參加訓練課程。」這題測驗副詞子句連接詞的語意與詞性。空格後方是完整的句子（主詞 they ＋動詞 have ＋受詞），所以空格必須填「連接詞」而非介系詞，這一點就先刪掉 (A) in spite of（片語介系詞，後面只能接名詞或動名詞，若要接子句得改成 in spite of the fact that）。剩下三個連接詞中，前後兩句是「有經驗」對「仍須受訓」的讓步轉折關係，因此 (B) even if（即使、就算）最貼切。選項 (C) as though 意為「好像、彷彿」，用於與事實不符的比喻；(D) in case 意為「以防萬一」，表預防目的，兩者填入後語意都不合邏輯。", "tags": ["連接詞", "讓步"]}, {"id": "國學閱讀綠本 第三回合#Q122", "src": "國學閱讀綠本 第三回合", "no": "Q122", "q": "All the team members will be traveling together aside from Ms. Bateman, who will be flying out ______ tomorrow.", "opts": ["physically", "partially", "separately", "commonly"], "ans": 2, "exp": "句意是「除了 Bateman 女士以外，所有團隊成員都會一起出發；她明天將會單獨（分開）搭機前往。」這題測驗副詞的字彙語意。判斷關鍵在前半句的對比線索：「will be traveling together aside from Ms. Bateman」（除了 Bateman 女士外都一起走），因此她的情況必然是「與大家分開、單獨行動」，(C) separately（分開地、各自地）正好與 together 形成對比。選項 (A) physically 指「身體上、實際上」，(B) partially 指「部分地」，(D) commonly 指「普遍地、常見地」，這三個副詞都無法用來描述與團隊分開行動的方式，因此 (C) 是唯一正確的答案。", "tags": ["字彙", "副詞"]}, {"id": "國學閱讀綠本 第三回合#Q124", "src": "國學閱讀綠本 第三回合", "no": "Q124", "q": "A company that adopts telecommuting practices allows its staff members to work ______ their location.", "opts": ["regardless of", "rather than", "on behalf of", "in exchange for"], "ans": 0, "exp": "句意是「採行遠距工作制度的公司，允許員工不論身在何處都能工作。」這題測驗片語介系詞的語意。空格後方是名詞片語 \"their location\"（他們的所在地），四個選項都是可接名詞的片語介系詞，所以要靠語意判斷：遠距工作（telecommuting）的核心精神就是「不受地點限制」，因此 (A) regardless of（不論、無論⋯⋯如何）最符合邏輯。選項 (B) rather than（而不是）用於兩者取捨對比；(C) on behalf of（代表某人）用於代理身分；(D) in exchange for（以⋯⋯作為交換）表示交換條件，這三者填入後語意都不通。", "tags": ["介系詞", "片語介系詞"]}, {"id": "國學閱讀綠本 第三回合#Q126", "src": "國學閱讀綠本 第三回合", "no": "Q126", "q": "Ms. Turner downloaded a free trial version of the program ______ she could test its features.", "opts": ["as if", "so that", "in order to", "because of"], "ans": 1, "exp": "句意是「Turner 女士下載了這個程式的免費試用版，以便測試它的各項功能。」判斷關鍵先看空格後方的結構：「she could test its features」是一個完整的句子（主詞 she ＋動詞 could test），所以空格必須是能引導子句的副詞子句連接詞。(C) in order to 後面只能接原形動詞（in order to test），(D) because of 是片語介系詞只能接名詞或動名詞，兩者詞性上就先出局。剩下的 (A) as if 意為「彷彿、好像」，用於與事實不符的假設，語意不合；(B) so that（以便、為了）正好表達下載試用版的目的，且常與 can／could／may 等助動詞連用，因此是正確答案。", "tags": ["連接詞", "目的"]}, {"id": "國學閱讀綠本 第三回合#Q128", "src": "國學閱讀綠本 第三回合", "no": "Q128", "q": "For the next group project, students are free to team up with ______ they want.", "opts": ["whomever", "which", "however", "whatever"], "ans": 0, "exp": "句意是「下一個小組專題，學生可以自由地與任何他們想要的人組隊。」這題測驗複合關係代名詞。空格前是介系詞 with，需要一個名詞性的結構當受詞；同時空格後方「they want」的動詞 want 也缺少受詞，這種前後都缺受詞的情況要用複合關係代名詞（本身含先行詞，等於 anyone whom）。因為組隊的對象是「人」，且在子句中擔任 want 的受詞，所以要用受格的 (A) whomever（＝anyone whom，任何⋯⋯的人）。選項 (B) which 是一般關係代名詞，不含先行詞、也不能直接放在介系詞後獨立使用；(C) however 是副詞（無論如何），不能當受詞；(D) whatever 雖然也是複合關係代名詞，但指「事物」而非人，與 team up with（與某人組隊）的語意不符。", "tags": ["關係代名詞", "複合關係代名詞"]}, {"id": "國學閱讀綠本 第三回合#Q129", "src": "國學閱讀綠本 第三回合", "no": "Q129", "q": "If politicians fail to follow through on their promises, they lose credibility and their reputations ______.", "opts": ["injure", "reject", "endure", "suffer"], "ans": 3, "exp": "句意是「如果政治人物未能履行承諾，他們會失去公信力，名聲也會受損。」這題測驗動詞的字彙語意與及物性。空格是 and 後面「their reputations ______」這個子句的動詞，而空格後沒有受詞，所以必須選一個能作不及物動詞、且主詞是「名聲」時語意通順的字。(D) suffer 作不及物動詞時意為「受損、變差、受苦」，\"their reputations suffer\"（名聲受損）是道地且常見的說法。選項 (A) injure（使受傷）與 (B) reject（拒絕）都是及物動詞，後面必須接受詞，且語意上名聲不會主動去傷害或拒絕什麼；(C) endure 意為「忍受」（及物）或「持續存在」（不及物），若解作「名聲持續下去」會與前半句「失去公信力」的負面語意矛盾。", "tags": ["字彙", "動詞"]}, {"id": "國學閱讀綠本 第三回合#Q130", "src": "國學閱讀綠本 第三回合", "no": "Q130", "q": "______ at work frequently is unprofessional, and it also makes coworkers feel uncomfortable.", "opts": ["Complained", "Complaint", "Complain", "Complaining"], "ans": 3, "exp": "句意是「在工作場合經常抱怨是不專業的，而且也會讓同事感到不舒服。」這題測驗動名詞當主詞的用法。句子的主要動詞是 is，前面缺少主詞，所以空格要填一個具名詞功能的字；再加上空格後方有副詞 frequently（經常）修飾，而副詞只能修飾動詞性質的結構，因此答案必須是兼具名詞與動詞性質的動名詞 (D) Complaining（抱怨這件事），動名詞作主詞視為單數，與 is 一致。選項 (C) Complain 是原形動詞，會使句子變成無主詞的命令句而與後面的 is 衝突；(A) Complained 是過去式／過去分詞，同樣不能當主詞；(B) Complaint 雖是名詞，但它是可數名詞，單獨使用必須加冠詞或改成複數（a complaint／complaints），而且名詞不能被副詞 frequently 修飾。", "tags": ["動名詞", "主詞"]}, {"id": "PREPEDU 第一回合#Q109", "src": "PREPEDU 第一回合", "no": "Q109", "q": "If he ______ earlier, he would not have missed the meeting.", "opts": ["leaves", "left", "had left", "would leave"], "ans": 2, "exp": "句意是「如果他早一點出發，就不會錯過那場會議了。」這題測驗與過去事實相反的假設語氣。判斷關鍵在主要子句的動詞 would not have missed——「would + have + 過去分詞」是與過去事實相反的固定結果句型，表示「（過去）本來就不會⋯⋯」，而與它配對的 if 子句必須用過去完成式，也就是 if + 主詞 + had + 過去分詞，所以答案是 (C) had left。這組公式（If + S + had p.p., S + would have p.p.）在多益屬於必考句型，看到其中一邊就能反推另一邊。(A) leaves 是現在簡單式，用於單純條件句（If he leaves earlier, he will not miss...），與 would have missed 的時態不搭；(B) left 是過去式，用於與「現在」事實相反的假設（If he left now, he would...），本句講的是已經發生的過去，時態退得不夠；(D) would leave 則犯了假設語氣的大忌——傳統文法規定 would 只出現在主要子句，不會放進 if 子句裡。", "tags": ["假設語氣", "時態"]}, {"id": "PREPEDU 第一回合#Q113", "src": "PREPEDU 第一回合", "no": "Q113", "q": "The company saw a significant ______ in productivity after implementing the new workflow system.", "opts": ["promotion", "increase", "formula", "incentive"], "ans": 1, "exp": "句意是「導入新的工作流程系統後，公司的生產力大幅提升。」四個選項都是名詞，都能接在 a significant 後面，所以這題考的是字彙語意與介系詞搭配。判斷關鍵有兩個：一是空格後的 in productivity（在生產力方面），二是句尾的 after implementing the new workflow system（導入新系統之後）——導入新系統帶來的是生產力的「增加」，而 an increase in + 名詞 正是英文表達「⋯⋯的增長」的固定搭配（反義為 a decrease in），因此 (B) increase 是正確答案。(A) promotion 指「升遷」或「促銷活動」，用在人事或行銷情境，不會用來描述生產力的變化；(C) formula 是「公式、配方」，與句子的因果邏輯無關；(D) incentive 意為「誘因、獎勵措施」，是促使人做某事的動機，慣用搭配是 an incentive for／to do something，語意上是「原因」而非新系統帶來的「結果」。", "tags": ["字彙", "名詞"]}, {"id": "PREPEDU 第一回合#Q116", "src": "PREPEDU 第一回合", "no": "Q116", "q": "______ interested in joining the research team should attend the informational meeting next week.", "opts": ["Whatever", "Whoever", "Anyone", "Whenever"], "ans": 2, "exp": "句意是「任何有興趣加入研究團隊的人，都應該參加下週的說明會。」這題測驗不定代名詞當主詞的用法。整句的主要動詞是 should attend，前面缺少主詞；而空格與 should 之間的 interested in joining the research team 並沒有動詞，它只是一段由 who are interested in joining... 省略關係代名詞與 be 動詞而來的形容詞片語，用來從後面修飾空格的字。因此空格必須填一個本身就能當主詞、又能被形容詞片語後位修飾的代名詞，(C) Anyone（任何人）正好符合，Anyone interested in joining... 就等於 Anyone who is interested in joining...。本題的陷阱是 (B) Whoever：它的中文意思同樣是「任何⋯⋯的人」，但它是複合關係代名詞，必須引導一個完整的名詞子句，子句裡要自備動詞，得寫成 Whoever is interested in joining... 才合法，本句沒有 is，所以不能選。(A) Whatever 指事物而非人；(D) Whenever 是表時間的副詞連接詞，不具名詞功能，這兩者都不能當主詞。", "tags": ["代名詞", "不定代名詞"]}, {"id": "PREPEDU 第一回合#Q118", "src": "PREPEDU 第一回合", "no": "Q118", "q": "The company's latest product will be unveiled ______ to capitalize on the upcoming trade show.", "opts": ["actually", "consequently", "promptly", "precisely"], "ans": 2, "exp": "句意是「公司最新的產品將迅速發表，以把握即將到來的貿易展。」四個選項都是副詞、詞性相同，所以這題純粹比較字彙語意。判斷關鍵在後半的目的片語 to capitalize on the upcoming trade show（善用即將到來的貿易展）：既然要趕上展會的商機，發表的時機就必須及時、不能拖延，因此表示「迅速地、立即地」的 (C) promptly 最貼切。(A) actually（實際上、事實上）用於修正或強調事實，與時間無關；(B) consequently（因此、結果）表達的是前因後果，但發表產品是為了搶展會商機，屬於目的而非結果；(D) precisely（精確地）強調數據或描述準確無誤，用來修飾 unveil（發表）語意不合。", "tags": ["字彙", "副詞"]}, {"id": "PREPEDU 第一回合#Q127", "src": "PREPEDU 第一回合", "no": "Q127", "q": "The team members were ______ for their outstanding performance on the project.", "opts": ["commended", "criticized", "reprimanded", "compromised"], "ans": 0, "exp": "句意是「團隊成員因為在這項專案上的傑出表現而受到表揚。」四個選項都是及物動詞的過去分詞，文法上都能填進被動語態 were ______ for，所以這題比的是字彙語意與褒貶。判斷關鍵在 for 後面的原因 their outstanding performance（他們傑出的表現）——既然是正面的表現，接續的結果也必須是正面的，因此 (A) commended（受到讚揚、表揚）是唯一合理的答案，be commended for... 也是職場上表達表揚的常見搭配。(B) criticized（受到批評）與 (C) reprimanded（受到申斥、訓誡）都是負面的處置，與「傑出表現」的原因互相矛盾；(D) compromised 意為「（原則、安全、資料）被損害、被危及」或「妥協」，主詞若是人指的是名譽或立場受損，同樣是負面語意，也無法與 for 引導的正面理由搭配。", "tags": ["字彙", "動詞"]}, {"id": "PREPEDU 第一回合#Q128", "src": "PREPEDU 第一回合", "no": "Q128", "q": "The company's decision to expand its operations internationally was driven by the desire for ______ growth.", "opts": ["vehicular", "exponential", "stagnant", "declined"], "ans": 1, "exp": "句意是「公司決定將營運拓展到國際市場，是出於對急遽成長的渴望。」四個選項都可以放在名詞 growth 前面當修飾語，所以這題考的是字彙語意是否與上下文邏輯相符。判斷關鍵在前半句的 decision to expand its operations internationally（決定向海外擴張）與 the desire for（渴望⋯⋯）——公司主動擴張、心之所嚮的必然是正面且大幅的成長，因此 (B) exponential（指數型的、急遽的）最貼切，exponential growth 也是商業英文中描述爆發性成長的固定搭配。(C) stagnant（停滯的）與 (D) declined（下降的）都是負面語意，公司不可能「渴望」停滯或衰退的成長，邏輯上互相矛盾（何況表達「衰退中的成長」慣用的是現在分詞 declining）；(A) vehicular 意為「車輛的」，只會用在 vehicular traffic（車流）這類搭配上，與 growth 完全無法連用。", "tags": ["字彙", "形容詞"]}, {"id": "PREPEDU 第一回合#Q129", "src": "PREPEDU 第一回合", "no": "Q129", "q": "The marketing strategies are ______ evaluated to ensure they meet the current market demands.", "opts": ["deliberately", "generously", "completely", "visually"], "ans": 2, "exp": "句意是「這些行銷策略都會被全面評估，以確保符合當前的市場需求。」四個選項都是副詞、詞性相同，所以這題比的是字彙語意與搭配。判斷關鍵在後面的目的 to ensure they meet the current market demands（確保符合當前市場需求）——要「確保」符合需求，評估就必須做得徹底、不能有遺漏，因此表示「完全地、徹底地」的 (C) completely 最貼切（同義的 thoroughly 也是常見說法）。(A) deliberately 現代用法主要是「刻意地、故意地」，強調行為出於本意，說「刻意評估」既不自然也無法呼應「確保符合需求」的完整性；(B) generously（慷慨地）用於給予金錢、時間或讚美，與評估無關；(D) visually（在視覺上）指從外觀來看，行銷策略是靠數據與成效檢視，不是用眼睛看的。", "tags": ["字彙", "副詞"]}, {"id": "PREPEDU 第一回合#Q130", "src": "PREPEDU 第一回合", "no": "Q130", "q": "To sustain its competitive edge in the market, the company's success hinges critically on ______ in its product development and marketing strategies.", "opts": ["innovation", "collaboration", "stagnation", "ambition"], "ans": 0, "exp": "句意是「為了維持在市場上的競爭優勢，公司的成功關鍵取決於產品開發與行銷策略上的創新。」四個選項都是名詞，都能當介系詞 on 的受詞，所以這題比的是字彙語意。判斷關鍵在句首的目的 To sustain its competitive edge in the market（維持市場競爭優勢）以及空格後的範圍 in its product development and marketing strategies（在產品開發與行銷策略方面）——能讓產品與行銷持續領先對手的，就是不斷推陳出新的能力，因此 (A) innovation（創新）最符合，也與 competitive edge 形成商業文章中常見的因果搭配。(B) collaboration（協作）是本題的陷阱，它雖然是正面詞，但一般會搭配對象或部門（collaboration with partners／between teams），用來說明「在產品開發上」如何維持競爭優勢並不是最直接的關鍵。(C) stagnation（停滯）語意負面，與維持競爭優勢完全矛盾；(D) ambition（企圖心、抱負）指的是個人或組織的心理企圖，無法用來修飾具體的產品開發與行銷做法。", "tags": ["字彙", "名詞"]}, {"id": "PREPEDU 第二回合#Q101", "src": "PREPEDU 第二回合", "no": "Q101", "q": "The board meeting has been postponed and will now be held ______ the first week of March.", "opts": ["during", "while", "as", "until"], "ans": 0, "exp": "句意是「董事會會議已延期，現在將於三月的第一週舉行。」這題測驗介系詞與連接詞的區別。空格後方的 the first week of March 是名詞片語，沒有主詞與動詞，所以空格只能填介系詞，而 (A) during（在⋯⋯期間）表示事件發生在某段時間之內，正好符合「在三月第一週舉行」的語意。(B) while 與 (C) as 都是副詞子句連接詞，後面必須接完整子句（while we are waiting／as the schedule changed）；(D) until 雖然也能當介系詞，但它表示動作持續到某個時間點為止，用在「開會」這種一次性事件上語意不通。", "tags": ["介系詞"]}, {"id": "PREPEDU 第二回合#Q102", "src": "PREPEDU 第二回合", "no": "Q102", "q": "All employees are required to complete their annual training modules ______ the end of the fiscal year.", "opts": ["by", "in", "until", "through"], "ans": 0, "exp": "句意是「所有員工都必須在會計年度結束前完成年度訓練課程。」這題測驗表期限的介系詞。complete（完成）是一次性完成的動作，搭配最後期限要用 (A) by（不遲於、在⋯⋯之前），by the end of the fiscal year 表示只要在年度結束前完成即可。(C) until 是本題陷阱，它用於持續性的狀態或動作延續到某時間為止（The office is open until six.），不能搭配一次完成的 complete；(B) in 後面接一段時間或月份年份（in March／in two weeks），不與 the end of 搭配表期限；(D) through 強調「從頭到尾持續整段時間」，語意也不是期限。", "tags": ["介系詞", "期限"]}, {"id": "PREPEDU 第二回合#Q103", "src": "PREPEDU 第二回合", "no": "Q103", "q": "The marketing team is looking for innovative ideas that can be easily ______ into the existing campaign.", "opts": ["integrates", "integrating", "integrated", "integration"], "ans": 2, "exp": "句意是「行銷團隊正在尋找能輕易融入現有行銷活動的創新想法。」判斷關鍵在空格前的 can be——助動詞 can 加上 be 之後接過去分詞，形成被動語態，而關係子句的主詞是先行詞 ideas（想法），想法是「被整合進活動裡」的一方，因此要用過去分詞 (C) integrated。(A) integrates 是第三人稱單數動詞、(D) integration 是名詞，都不能接在 be 之後構成這個結構；(B) integrating 接在 be 後面會變成進行式，語意成了「想法主動去整合別人」，與 into the existing campaign 的被動語意不符。", "tags": ["語態", "被動"]}, {"id": "PREPEDU 第二回合#Q104", "src": "PREPEDU 第二回合", "no": "Q104", "q": "Due to unforeseen circumstances, the project deadline has been ______ to give the team additional time for completion.", "opts": ["extending", "extended", "extension", "extend"], "ans": 1, "exp": "句意是「由於突發狀況，專案期限已經延長，以便給團隊更多時間完成。」判斷關鍵在空格前的 has been——「has been + 過去分詞」是現在完成式的被動語態，而主詞 the project deadline（期限）是被延長的對象，因此要填過去分詞 (B) extended。(A) extending 會變成現在完成進行式，語意成了「期限主動在延長某物」，不合邏輯；(C) extension 是名詞；(D) extend 是原形動詞，兩者都不能接在 has been 之後。", "tags": ["語態", "時態"]}, {"id": "PREPEDU 第二回合#Q105", "src": "PREPEDU 第二回合", "no": "Q105", "q": "Before we start the meeting, please go over the document I shared ______ your convenience.", "opts": ["by", "on", "at", "with"], "ans": 2, "exp": "句意是「開會前，請在您方便的時候看過我分享的那份文件。」這題考固定片語。at your convenience（在您方便的時候）是商務書信與職場對話的慣用說法，常再加強成 at your earliest convenience（請盡早）。其餘介系詞都無法與 convenience 搭配出這個意思：(A) by 表期限或方法，(B) on 表接觸面或日期，(D) with 表工具或伴隨，填入後都不成立。", "tags": ["介系詞", "慣用語"]}, {"id": "PREPEDU 第二回合#Q106", "src": "PREPEDU 第二回合", "no": "Q106", "q": "The project team ______ on the new initiative since last month and is making significant progress.", "opts": ["has been working", "works", "worked", "is working"], "ans": 0, "exp": "句意是「專案團隊自上個月起就一直在推動這項新計畫，並且進展顯著。」判斷關鍵是時間標記 since last month（自上個月以來）——since 表示動作從過去某個時間點一直持續到現在，必須搭配現在完成式或現在完成進行式，因此 (A) has been working 正確，還能強調動作持續不斷。(B) works 是現在簡單式，講的是習慣或事實；(D) is working 是現在進行式，只描述此刻，兩者都不能與 since 連用；(C) worked 是過去式，表示動作已在過去結束，與後半句 is making significant progress（現在仍在進展）互相矛盾。", "tags": ["時態", "現在完成式"]}, {"id": "PREPEDU 第二回合#Q107", "src": "PREPEDU 第二回合", "no": "Q107", "q": "This year's performance is ______ than last year's, indicating substantial growth.", "opts": ["better", "best", "good", "well"], "ans": 0, "exp": "句意是「今年的表現比去年更好，顯示出大幅的成長。」判斷關鍵在空格後方的 than——than 是比較級的標記，前面必須是比較級形式，因此要用 good 的比較級 (A) better。(B) best 是最高級，須搭配 the 且不與 than 連用；(C) good 是原級，只能用在 as good as 的同級比較；(D) well 是副詞（意為「良好地」或指身體健康），這裡空格接在 be 動詞後面用來描述主詞 performance，需要形容詞性質的補語，且它本身也不是比較級。", "tags": ["比較級"]}, {"id": "PREPEDU 第二回合#Q108", "src": "PREPEDU 第二回合", "no": "Q108", "q": "The quarterly earnings report ______ published by the finance department next week.", "opts": ["was", "has been", "will be", "is"], "ans": 2, "exp": "句意是「季度財報將由財務部門在下週發布。」空格後的 published 是過去分詞，可知句子是被動語態，空格要填的是 be 動詞，而時態由句尾的時間副詞 next week（下週）決定，因此選 (C) will be，形成 will be published（將被發布）。(A) was 是過去式、(B) has been 是現在完成式，都與「下週」這個未來時間衝突；(D) is 是現在式，雖然現在簡單式偶爾能表既定行程，但那限於時刻表類的事件（The train leaves at six.），此處搭配 next week 仍以 will be 為標準答案。", "tags": ["時態", "語態"]}, {"id": "PREPEDU 第二回合#Q109", "src": "PREPEDU 第二回合", "no": "Q109", "q": "If the client approves the proposal, the project ______ by the end of the month.", "opts": ["starts", "would start", "will start", "started"], "ans": 2, "exp": "句意是「如果客戶批准這份提案，專案將在月底前啟動。」這題測驗第一類條件句（描述有可能發生的未來）。公式是「If + 現在簡單式，主要子句用 will + 原形動詞」；題目的 if 子句已經用了現在式 approves，所以主要子句要用 (C) will start。(A) starts 是現在式，不用在主要子句表未來結果；(B) would start 屬於與現在事實相反的第二類條件句，若要用它，if 子句得改成過去式 approved；(D) started 是過去式，與 by the end of the month 的未來時間不合。", "tags": ["條件句", "時態"]}, {"id": "PREPEDU 第二回合#Q110", "src": "PREPEDU 第二回合", "no": "Q110", "q": "The team worked ______ to complete the project before the deadline.", "opts": ["hard", "hardly", "harder", "hardest"], "ans": 0, "exp": "句意是「團隊努力工作，以便在期限前完成專案。」空格要修飾前面的動詞 worked，需要副詞，而 (A) hard 本身既是形容詞也是副詞，work hard（努力工作）是固定搭配。本題最大的陷阱是 (B) hardly：它雖然有 -ly 字尾，意思卻不是「努力地」而是「幾乎不」（He hardly worked. 他幾乎沒在工作），語意完全相反。(C) harder 是比較級、(D) hardest 是最高級，句中既沒有比較對象也沒有 the，都不適用。", "tags": ["副詞", "字彙"]}, {"id": "PREPEDU 第二回合#Q111", "src": "PREPEDU 第二回合", "no": "Q111", "q": "We need to order ______ chairs for the new conference room.", "opts": ["much", "little", "few", "many"], "ans": 3, "exp": "句意是「我們需要為新的會議室訂購許多椅子。」這題測驗數量詞與名詞可數性的搭配。chairs 是可數名詞的複數，而且語意上是「為新會議室添購一批」，因此要用修飾可數複數、表示「許多」的 (D) many。(A) much 只能修飾不可數名詞（much water）；(B) little 同樣修飾不可數名詞，且意為「很少」；(C) few 雖然可以修飾可數複數，但意思是「很少、幾乎沒有」，與訂購椅子布置新會議室的語意不合。", "tags": ["數量詞"]}, {"id": "PREPEDU 第二回合#Q112", "src": "PREPEDU 第二回合", "no": "Q112", "q": "The manager expects ______ the report by tomorrow.", "opts": ["submitting", "submitted", "to submit", "submits"], "ans": 2, "exp": "句意是「經理預期在明天之前提交這份報告。」這題測驗動詞後面該接哪種形式。expect 屬於接不定詞的動詞（expect to do something／expect someone to do something），因此選 (C) to submit。(A) submitting 是動名詞，不能直接當 expect 的受詞；(B) submitted 是過去式或過去分詞；(D) submits 是動詞，而句子已有主要動詞 expects，不能再並列一個限定動詞。", "tags": ["不定詞", "動狀詞"]}, {"id": "PREPEDU 第二回合#Q113", "src": "PREPEDU 第二回合", "no": "Q113", "q": "She is looking forward ______ the team in the upcoming project.", "opts": ["to lead", "to leading", "lead", "leading"], "ans": 1, "exp": "句意是「她很期待在接下來的專案中帶領團隊。」關鍵在 look forward to 這個片語——當中的 to 是介系詞，不是不定詞的 to，所以後面必須接名詞或動名詞，因此答案是 (B) to leading。(A) to lead 正是本題陷阱，它誤把 to 當成不定詞；(C) lead 與 (D) leading 都漏掉了片語不可省略的 to。同類考點還有 be used to、object to、be committed to、look forward to，後面一律接 V-ing。", "tags": ["動名詞", "片語"]}, {"id": "PREPEDU 第二回合#Q114", "src": "PREPEDU 第二回合", "no": "Q114", "q": "We can start the meeting as soon as the director ______.", "opts": ["arrives", "will arrive", "would arrive", "arriving"], "ans": 0, "exp": "句意是「主管一到，我們就可以開始會議。」as soon as 引導的是表時間的副詞子句，而英文文法規定時間與條件副詞子句「不用 will，改用現在簡單式代替未來」，因此選 (A) arrives。(B) will arrive 是本題陷阱，中文「將會到」很容易誘導人選它；(C) would arrive 是過去未來式，與主要子句的 can start 時態不合；(D) arriving 是分詞，會讓子句缺少限定動詞。", "tags": ["時態", "副詞子句"]}, {"id": "PREPEDU 第二回合#Q115", "src": "PREPEDU 第二回合", "no": "Q115", "q": "The files are stored ______ the cloud for easy access.", "opts": ["in", "within", "at", "by"], "ans": 0, "exp": "句意是「檔案儲存在雲端，方便隨時取用。」這題考介系詞的慣用搭配。談到雲端儲存，英文固定說 in the cloud——把雲端視為一個容納資料的空間，因此選 (A) in。(B) within 雖然也表示「在⋯⋯之內」，但通常強調範圍或期限（within the company／within two days），不用於這個固定說法；(C) at 用於具體的地點或位置點；(D) by 表示方法或「在旁邊」，語意都不符。", "tags": ["介系詞"]}, {"id": "PREPEDU 第二回合#Q116", "src": "PREPEDU 第二回合", "no": "Q116", "q": "Can you explain how ______ the new software?", "opts": ["to use", "used", "using", "uses"], "ans": 0, "exp": "句意是「你可以說明一下這個新軟體要怎麼使用嗎？」關鍵在疑問詞 how 之後的結構：「疑問詞 + to + 原形動詞」構成一個名詞片語（how to use＝使用的方法），可以直接當 explain 的受詞，因此選 (A) to use。(B) used、(C) using、(D) uses 都無法接在 how 後面組成這個名詞片語；若要改用子句，就必須補上主詞與助動詞（explain how I can use the new software）。", "tags": ["不定詞"]}, {"id": "PREPEDU 第二回合#Q117", "src": "PREPEDU 第二回合", "no": "Q117", "q": "By the end of this year, the company ______ its 10th anniversary.", "opts": ["will celebrate", "will have celebrated", "celebrates", "would have celebrated"], "ans": 1, "exp": "句意是「到今年年底時，公司將已慶祝過創立十週年。」判斷關鍵是句首的 By the end of this year——「by + 未來時間點」表示動作會在那個時間之前完成，正是未來完成式的標記，因此選 (B) will have celebrated。(A) will celebrate 只是單純未來式，無法表達「在該時間點之前就已完成」；(C) celebrates 是現在式；(D) would have celebrated 是與過去事實相反的假設語氣，與未來的年底完全矛盾。", "tags": ["時態", "未來完成式"]}, {"id": "PREPEDU 第二回合#Q118", "src": "PREPEDU 第二回合", "no": "Q118", "q": "If he ______ the job, he wouldn't be looking for a new one now.", "opts": ["liked", "would like", "had liked", "likes"], "ans": 0, "exp": "句意是「如果他喜歡這份工作，現在就不會在找新工作了。」這題測驗與現在事實相反的假設語氣。判斷關鍵是主要子句的 wouldn't be looking 以及時間副詞 now——「would + 原形動詞」的結果句所搭配的 if 子句必須用過去式，因此選 (A) liked。(D) likes 是現在式，那是單純條件句的用法（If he likes the job, he will stay.）；(C) had liked 是過去完成式，用於與過去事實相反的假設，結果句要改成 wouldn't have been looking；(B) would like 則犯了 would 不放進 if 子句的規則。", "tags": ["假設語氣"]}, {"id": "PREPEDU 第二回合#Q119", "src": "PREPEDU 第二回合", "no": "Q119", "q": "The team's performance, ______ was exceptional, exceeded all expectations.", "opts": ["whose", "who's", "which", "that"], "ans": 2, "exp": "句意是「團隊的表現十分出色，超出了所有人的預期。」空格前有逗號，可知這是非限定關係子句，用來補充說明先行詞 The team's performance（事物），而子句 ______ was exceptional 缺少主詞，所以要用主格的關係代名詞 (C) which。(D) that 是本題陷阱——that 不能用在逗號後的非限定子句裡；(A) whose 是所有格，後面必須緊接名詞；(B) who's 是 who is 的縮寫，而且 who 只能指人。", "tags": ["關係代名詞", "非限定"]}, {"id": "PREPEDU 第二回合#Q120", "src": "PREPEDU 第二回合", "no": "Q120", "q": "The project manager ______ the project timeline is known for his leadership skills.", "opts": ["who establish", "establishing", "to establish", "established"], "ans": 1, "exp": "句意是「負責制定專案時程的那位專案經理以領導能力著稱。」整句的主要動詞是後面的 is known，所以空格不能再放一個並列的主要動詞，而是要填一段修飾 The project manager 的後位修飾語。(B) establishing 是現在分詞，相當於省略關係代名詞的 who establishes（主動制定時程），修飾人合乎邏輯，因此正確。(A) who establish 結構雖然對，但先行詞 The project manager 是單數，動詞應為 establishes，主動詞一致性錯誤；(C) to establish 的不定詞在此會被解讀成「為了制定」的目的，語意不合；(D) established 是過去分詞，表被動（被制定），而經理不是被制定的對象。", "tags": ["分詞", "修飾"]}, {"id": "PREPEDU 第二回合#Q121", "src": "PREPEDU 第二回合", "no": "Q121", "q": "The board demands that he ______ the report by tomorrow without fail.", "opts": ["submits", "submit", "submitted", "shall submit"], "ans": 1, "exp": "句意是「董事會要求他務必在明天前提交報告。」這題測驗表「要求、建議、命令、堅持」的動詞後面 that 子句的假設語氣。demand、request、suggest、insist、recommend、require 等字後面的 that 子句要用「(should) + 原形動詞」，而 should 通常省略，所以即使主詞是第三人稱單數也用原形 (B) submit。(A) submits 加了 s 就違反這條規則，正是本題陷阱；(C) submitted 是過去式，與 by tomorrow 也矛盾；(D) shall submit 的 shall 不用於這個結構。", "tags": ["假設語氣", "動詞原形"]}, {"id": "PREPEDU 第二回合#Q122", "src": "PREPEDU 第二回合", "no": "Q122", "q": "Mr. Sims needs a more ______ car for traveling from his suburban home to his office downtown.", "opts": ["decorative", "reliable", "occasional", "adventurous"], "ans": 1, "exp": "句意是「Sims 先生需要一輛更可靠的車，好從郊區的家通勤到市區的辦公室。」四個選項都是形容詞，所以這題比的是語意。判斷關鍵在 for traveling from his suburban home to his office downtown（每天長距離通勤）——通勤最在意的就是車子不會出狀況，因此 (B) reliable（可靠的、不易故障的）最貼切。(A) decorative（裝飾性的）與通勤需求無關；(C) occasional（偶爾的）用來修飾頻率，不能形容車；(D) adventurous（愛冒險的）是形容人的性格，都不合邏輯。", "tags": ["字彙", "形容詞"]}, {"id": "PREPEDU 第二回合#Q123", "src": "PREPEDU 第二回合", "no": "Q123", "q": "The company has made significant advancements ______ the field of renewable energy.", "opts": ["in", "into", "onto", "around"], "ans": 0, "exp": "句意是「該公司在再生能源領域取得了重大進展。」這題考介系詞與名詞的固定搭配：表達「在某個領域」時用 in the field of...，而 make advancements／progress in + 領域 也是常見組合，因此選 (A) in。(B) into 表示進入內部的移動方向；(C) onto 表示移動到某個表面上；(D) around 表示環繞或「大約」，三者都無法與 the field 搭配表示「在某領域中」。", "tags": ["介系詞"]}, {"id": "PREPEDU 第二回合#Q124", "src": "PREPEDU 第二回合", "no": "Q124", "q": "The employees are ______ with the new health benefits plan.", "opts": ["satisfying", "satisfied", "satisfy", "satisfies"], "ans": 1, "exp": "句意是「員工們對新的健康福利方案感到滿意。」這題測驗情緒動詞的分詞用法：修飾「感受到情緒的人」用過去分詞，修飾「引發情緒的事物」用現在分詞。這裡主詞是 The employees（人），是感到滿意的一方，因此用 (B) satisfied，而且 be satisfied with 是固定搭配（介系詞用 with，不用 by）。(A) satisfying 意為「令人滿意的」，是用來形容方案本身（The plan is satisfying.）；(C) satisfy 是原形動詞、(D) satisfies 是第三人稱單數動詞，都不能接在 be 動詞後面。", "tags": ["分詞", "情緒動詞"]}, {"id": "PREPEDU 第二回合#Q125", "src": "PREPEDU 第二回合", "no": "Q125", "q": "We want to talk about this issue honestly and ______ at the upcoming team meeting.", "opts": ["rarely", "openly", "early", "highly"], "ans": 1, "exp": "句意是「我們希望在接下來的團隊會議上誠實且公開地討論這個議題。」關鍵在對等連接詞 and——它把空格與前面的副詞 honestly（誠實地）連接起來，因此空格不只詞性要一致（四個選項都是副詞），語意也必須相配。(B) openly（公開地、坦率地）與 honestly 同屬「坦白說出來」的正面態度，是最自然的搭配。(A) rarely（很少）表頻率，與 honestly 並列語意衝突；(C) early（提早）講的是時間；(D) highly（高度地）通常修飾形容詞或特定動詞（highly recommend），都無法與 honestly 對等並列。", "tags": ["副詞", "字彙"]}, {"id": "PREPEDU 第二回合#Q126", "src": "PREPEDU 第二回合", "no": "Q126", "q": "The manager, ______ proposal was accepted, will speak at the conference.", "opts": ["who", "whom", "whose", "which"], "ans": 2, "exp": "句意是「那位提案獲得採納的經理將在會議上發言。」判斷關鍵在空格後方緊接著名詞 proposal（提案），而語意是「經理的提案」，這種所屬關係要用所有格關係代名詞 (C) whose。(A) who 是主格，後面要接動詞；(B) whom 是受格，後面要接主詞加動詞；(D) which 用來指事物，而且同樣不具所有格功能。", "tags": ["關係代名詞", "所有格"]}, {"id": "PREPEDU 第二回合#Q127", "src": "PREPEDU 第二回合", "no": "Q127", "q": "The director agreed ______ the new policy by the end of the month.", "opts": ["implements", "implementing", "implementation", "to implement"], "ans": 3, "exp": "句意是「主管同意在月底前實施這項新政策。」這題測驗動詞後面接的形式。agree 屬於接不定詞的動詞（agree to do something），因此選 (D) to implement。(B) implementing 是動名詞，agree 不直接接動名詞；(C) implementation 是名詞，agree 也不能直接接名詞當受詞（要說 agreed to the implementation of...）；(A) implements 是動詞，而句子已有主要動詞 agreed。", "tags": ["不定詞", "動狀詞"]}, {"id": "PREPEDU 第二回合#Q128", "src": "PREPEDU 第二回合", "no": "Q128", "q": "______ is essential for all team members to cooperate to meet the project deadline.", "opts": ["it", "They", "This", "Those"], "ans": 0, "exp": "句意是「所有團隊成員通力合作以趕上專案期限，是不可或缺的。」這題測驗虛主詞句型「It is + 形容詞 + for 某人 + to do something」——真正的主詞是後面的不定詞片語 to cooperate...，因為太長而移到句尾，句首用虛主詞 It 佔位，因此選 (A)（放在句首時要大寫成 It）。(B) They 與 (D) Those 是複數代名詞，會與單數動詞 is 不一致，句中也找不到它們指涉的對象；(C) This 雖是單數，但必須指前文提過的特定事物，不能充當引導不定詞真主詞的虛主詞。", "tags": ["虛主詞", "句型"]}, {"id": "PREPEDU 第二回合#Q129", "src": "PREPEDU 第二回合", "no": "Q129", "q": "The manager avoided ______ the issue during the meeting, which led to further confusion.", "opts": ["to address", "addressing", "addressed", "address"], "ans": 1, "exp": "句意是「經理在會議上避免處理這個問題，這導致了後續更多的混亂。」這題測驗動詞後面接的形式。avoid 屬於只接動名詞的動詞（avoid + V-ing），同類還有 enjoy、mind、finish、suggest、consider、practice，因此選 (B) addressing。(A) to address 是不定詞，avoid 不接不定詞，正是本題陷阱；(C) addressed 是過去式或過去分詞；(D) address 是原形動詞，都不能直接當 avoid 的受詞。", "tags": ["動名詞", "動狀詞"]}, {"id": "PREPEDU 第二回合#Q130", "src": "PREPEDU 第二回合", "no": "Q130", "q": "The baseball player participated in the last game of the season ______ an ankle injury.", "opts": ["despite", "although", "because of", "unless"], "ans": 0, "exp": "句意是「儘管腳踝受傷，那位棒球選手還是參加了本季的最後一場比賽。」判斷關鍵有兩個：一是空格後方的 an ankle injury 是名詞片語、沒有主詞與動詞，所以只能用介系詞；二是前後語意相反（受傷卻仍上場），需要表讓步的字，因此選 (A) despite（＝in spite of，儘管）。(B) although 語意雖然對，但它是連接詞，後面必須接完整子句（although he had an ankle injury）；(C) because of 雖然也是片語介系詞，但表原因，會變成「因為受傷所以參賽」的錯誤邏輯；(D) unless（除非）是表條件的連接詞，同樣要接子句。", "tags": ["介系詞", "讓步"]}, {"id": "國學閱讀綠本 第四回合#Q107", "src": "國學閱讀綠本 第四回合", "no": "Q107", "q": "The Medland hiring manager ______ that writing samples be submitted along with resumes.", "opts": ["inquired", "requested", "persuaded", "predicted"], "ans": 1, "exp": "句意是「Medland 的招募主管要求寫作範本要與履歷一併提交。」判斷關鍵在 that 子句裡的動詞是原形 be submitted（而非 is/should be）——這是「要求、建議、命令」類動詞後方 that 子句用假設語氣（that + S + 原形動詞）的標記，request 正是這類動詞，因此選 (B)。(A) inquired（詢問）雖可接 that 子句，但語意是「問到某事」，不會帶出原形動詞的假設語氣；(C) persuaded 要用 persuade someone to do 的句型，不能直接接 that 子句提出要求；(D) predicted（預測）後面的 that 子句要用一般時態（predicted that samples would be submitted），不用原形。", "tags": ["假設語氣", "動詞用法"]}, {"id": "國學閱讀綠本 第四回合#Q117", "src": "國學閱讀綠本 第四回合", "no": "Q117", "q": "Having no experience operating a retail store, Ms. Philips relied ______ her business partner's advice.", "opts": ["upon", "beside", "toward", "with"], "ans": 0, "exp": "句意是「由於沒有經營零售店的經驗，Philips 女士依賴她事業夥伴的建議。」這題考的是動詞與介系詞的固定搭配：rely on / rely upon（依賴），upon 是 on 的正式用法，因此選 (A)。(B) beside（在…旁邊）、(C) toward（朝向）、(D) with（和…一起）雖然都是介系詞，但都不能與 rely 搭配。", "tags": ["介系詞", "動詞搭配"]}, {"id": "國學閱讀綠本 第四回合#Q118", "src": "國學閱讀綠本 第四回合", "no": "Q118", "q": "Regardless of seniority, ______ employee is entitled to 15 days of paid vacation per year.", "opts": ["each", "which", "some", "those"], "ans": 0, "exp": "句意是「無論年資長短，每一位員工每年都享有 15 天的有薪假。」判斷關鍵在空格後是單數可數名詞 employee，動詞也是單數 is，因此要選能修飾單數名詞的限定詞 (A) each（每一個）。(B) which 是關係代名詞或疑問詞，放在句首會變成疑問句或需要先行詞；(C) some 後面要接複數名詞（some employees）或不可數名詞；(D) those 是複數指示詞，會與單數的 employee is 不一致。", "tags": ["限定詞", "單複數"]}, {"id": "國學閱讀綠本 第四回合#Q120", "src": "國學閱讀綠本 第四回合", "no": "Q120", "q": "______ staff members dress is a reflection on the company, so please wear professional attire throughout the workweek.", "opts": ["When", "What", "How", "Who"], "ans": 2, "exp": "句意是「員工的穿著方式反映了公司的形象，所以整個工作週請穿著專業服裝。」這裡空格帶出一個當主詞用的名詞子句（後面接主要動詞 is）。子句 staff members dress 本身已完整——dress 在此是不及物動詞（穿著），主詞受詞都不缺，缺的是「方式」這個副詞概念，因此用 (C) How（＝穿著的方式）。(B) What 必須在子句中充當缺少的主詞或受詞，這裡沒有空缺；(A) When 表時間，與「反映公司形象」的語意不合；(D) Who 會取代主詞位置，但主詞 staff members 已經存在。", "tags": ["名詞子句", "疑問詞"]}, {"id": "國學閱讀綠本 第四回合#Q121", "src": "國學閱讀綠本 第四回合", "no": "Q121", "q": "The annual Independence Day fireworks show will ______ at 8 P.M. behind Stapleton Park.", "opts": ["enter", "commence", "withstand", "originate"], "ans": 1, "exp": "句意是「一年一度的國慶煙火秀將於晚上 8 點在 Stapleton 公園後方開始。」空格後直接接時間與地點副詞、沒有受詞，需要一個表「開始」的不及物動詞，(B) commence（開始，＝begin 的正式用法）語意與句構都相符。(A) enter（進入）是及物動詞，要接受詞；(C) withstand（承受、抵擋）也是及物動詞，且語意不合；(D) originate（起源）雖可不及物，但通常搭配 from/in 說明來源，用在「活動於幾點開始」不正確。", "tags": ["字彙", "動詞"]}, {"id": "國學閱讀綠本 第四回合#Q123", "src": "國學閱讀綠本 第四回合", "no": "Q123", "q": "Ms. Sutter left some portions of the registration form ______ because she did not know all of the information necessary to complete it.", "opts": ["hollow", "flat", "blank", "pure"], "ans": 2, "exp": "句意是「Sutter 女士把報名表的部分欄位留空，因為她不知道填完表格所需的全部資訊。」這裡是「leave + 受詞 + 形容詞」的句型，空格當受詞補語，形容 some portions of the form 的狀態；表格欄位沒填要用 (C) blank（空白的，leave it blank 是固定說法）。(A) hollow 指物體「中空的」；(B) flat 指「平坦的」；(D) pure 指「純淨的」，都不能用來形容未填寫的表格欄位。", "tags": ["字彙", "形容詞"]}, {"id": "國學閱讀綠本 第四回合#Q124", "src": "國學閱讀綠本 第四回合", "no": "Q124", "q": "Dearden Inc. must comply with safety regulations by placing ______ visible emergency exit signs on every floor.", "opts": ["clears", "clearance", "clearly", "cleared"], "ans": 2, "exp": "句意是「Dearden 公司必須在每一層樓設置清楚可見的緊急出口標示，以符合安全法規。」判斷關鍵在空格後是形容詞 visible——修飾形容詞要用副詞，因此選 (C) clearly（clearly visible＝清楚可見）。(A) clears 是動詞第三人稱單數；(B) clearance 是名詞（清除、淨空）；(D) cleared 是過去分詞，三者都不能修飾形容詞。", "tags": ["副詞", "詞性"]}, {"id": "國學閱讀綠本 第四回合#Q128", "src": "國學閱讀綠本 第四回合", "no": "Q128", "q": "Ray's Sandwiches opened 10 years ago and has ______ become a popular lunch spot for office workers in Weyburn.", "opts": ["yet", "since", "still", "while"], "ans": 1, "exp": "句意是「Ray's Sandwiches 十年前開幕，此後便成為 Weyburn 上班族熱門的午餐去處。」前半句用過去式點出 10 years ago 這個過去時間點，後半句用現在完成式 has become，需要一個表「從那時以來」的副詞把兩者連起來，因此選 (B) since（此後，此處作副詞用，have since done 是常見搭配）。(A) yet 用於否定句或疑問句（has not yet become）；(C) still（仍然）表狀態延續，與「後來變成」的語意不合；(D) while 是連接詞，後面要接子句，不能插在助動詞與過去分詞之間。", "tags": ["副詞", "現在完成式"]}, {"id": "國學閱讀綠本 第四回合#Q129", "src": "國學閱讀綠本 第四回合", "no": "Q129", "q": "______ a few typos that can be easily fixed, the report looks ready to be submitted.", "opts": ["Supposing", "In case", "As though", "Apart from"], "ans": 3, "exp": "句意是「除了幾個容易修正的錯字之外，這份報告看起來已經可以送出了。」判斷關鍵在空格後方是名詞片語 a few typos...（沒有主詞加動詞），所以只能用片語介系詞；語意上也是「把小瑕疵排除在外」，因此選 (D) Apart from（除了…之外，＝aside from）。(A) Supposing（假如）、(B) In case（以防）、(C) As though（好像）都是連接詞，後面必須接完整子句。", "tags": ["介系詞", "片語"]}, {"id": "國學閱讀綠本 第四回合#Q130", "src": "國學閱讀綠本 第四回合", "no": "Q130", "q": "Astrophysicist Dr. Bryan Healy and aerospace engineer Dr. Marie Duns are experts in their ______ fields.", "opts": ["plausible", "respective", "negligible", "intrusive"], "ans": 1, "exp": "句意是「天文物理學家 Healy 博士與航太工程師 Duns 博士各自是其領域的專家。」句子提到兩位分屬不同專業的學者，搭配複數 fields，需要表「各自的、分別的」之意，因此選 (B) respective（their respective fields＝他們各自的領域）。(A) plausible（似乎合理的）、(C) negligible（微不足道的）、(D) intrusive（侵擾的）語意都與「兩人分屬不同領域」無關。", "tags": ["字彙", "形容詞"]}, {"id": "國學閱讀綠本 第五回合#Q110", "src": "國學閱讀綠本 第五回合", "no": "Q110", "q": "Emblem Motor's new car lineup will be unveiled at the annual Chicago Auto Show ______ next year.", "opts": ["previously", "typically", "early", "highly"], "ans": 2, "exp": "句意是「Emblem 汽車的新車系列將在明年年初的芝加哥車展上亮相。」判斷關鍵在空格後面接的是時間詞 next year，能直接修飾時間詞、組成「early next year（明年年初）」的只有 (C) early。(A) previously（先前）指過去，與 next year 的未來時間矛盾；(B) typically（通常）表頻率，不能修飾特定時間點；(D) highly（高度地）用來修飾形容詞或動詞（highly recommended），不能修飾時間。", "tags": ["字彙", "副詞"]}, {"id": "國學閱讀綠本 第五回合#Q112", "src": "國學閱讀綠本 第五回合", "no": "Q112", "q": "When companies prioritize their customers' needs ______ all else, they tend to generate repeat business.", "opts": ["above", "where", "within", "toward"], "ans": 0, "exp": "句意是「當公司把顧客的需求擺在一切之上時，往往能帶來回頭生意。」這題考固定搭配 prioritize / put A above B（把 A 看得比 B 重要），above all else 是「凌駕於其他一切之上」的常用說法，因此選 (A)。(B) where 是關係副詞或連接詞，後面要接子句，這裡只有名詞 all else；(C) within（在…之內）、(D) toward（朝向）語意都與「優先於」不合。", "tags": ["介系詞", "片語"]}, {"id": "國學閱讀綠本 第五回合#Q113", "src": "國學閱讀綠本 第五回合", "no": "Q113", "q": "The engineers claimed that making a slight ______ to the existing solar panels would make them more effective.", "opts": ["modify", "modified", "modifiable", "modification"], "ans": 3, "exp": "句意是「工程師表示，只要對現有的太陽能板做一點小幅修改，就能讓效能更好。」判斷關鍵在空格前有冠詞 a 與形容詞 slight，空格要當 making 的受詞，所以必須填名詞，選 (D) modification（修改）。(A) modify 是動詞原形；(B) modified 是過去式／過去分詞；(C) modifiable 是形容詞（可修改的），都不能被 a slight 修飾當受詞。", "tags": ["詞性", "名詞"]}, {"id": "國學閱讀綠本 第五回合#Q118", "src": "國學閱讀綠本 第五回合", "no": "Q118", "q": "Manuel Corporation workers will now receive life insurance coverage as one of their employment ______.", "opts": ["skills", "benefits", "concerns", "deductions"], "ans": 1, "exp": "句意是「Manuel 公司的員工現在可以獲得壽險保障，作為其工作福利之一。」壽險保障屬於公司提供給員工的待遇，employment benefits（員工福利）是固定說法，因此選 (B)。(A) skills（技能）是員工具備的能力，不是公司給的；(C) concerns（疑慮、關切）語意不合；(D) deductions（扣除額）指從薪水扣掉的錢，與「receive（獲得）」矛盾。", "tags": ["字彙", "名詞"]}, {"id": "國學閱讀綠本 第五回合#Q120", "src": "國學閱讀綠本 第五回合", "no": "Q120", "q": "This weekend's Phoenix Marathon is going to take place as planned ______ the forecast of rainy weather.", "opts": ["aside from", "notwithstanding", "regarding", "according to"], "ans": 1, "exp": "句意是「儘管氣象預報說會下雨，本週末的鳳凰城馬拉松仍將照原訂計畫舉行。」前後兩件事（會下雨 vs. 照常舉行）語意相反，需要表讓步的介系詞，(B) notwithstanding（儘管，＝despite / in spite of）最符合。(A) aside from（除了…之外）是排除語氣；(C) regarding（關於）只帶出主題；(D) according to（根據）會變成「依照雨天預報而照常舉行」，邏輯不通。", "tags": ["介系詞", "讓步"]}, {"id": "國學閱讀綠本 第五回合#Q121", "src": "國學閱讀綠本 第五回合", "no": "Q121", "q": "Visitors to the Shiller Children's Museum are more than ______ to interact with the items on display.", "opts": ["pleasant", "welcome", "obvious", "brilliant"], "ans": 1, "exp": "句意是「Shiller 兒童博物館的參觀者非常歡迎去觸摸互動展示的物品。」這題考固定用法 be (more than) welcome to do something（儘管去做…、非常歡迎做…），more than 在此是「非常」的加強語氣，因此選 (B)。(A) pleasant（令人愉快的）用來形容人或事物給人的感受，不能接 to do 表許可；(C) obvious（明顯的）、(D) brilliant（傑出的）語意都不合。", "tags": ["字彙", "形容詞"]}, {"id": "國學閱讀綠本 第五回合#Q124", "src": "國學閱讀綠本 第五回合", "no": "Q124", "q": "The musicians practiced in the back room ______ the stage was being set up.", "opts": ["in order to", "as", "during", "unless"], "ans": 1, "exp": "句意是「舞台正在架設的同時，樂手們在後方房間練習。」判斷關鍵在空格後是完整子句 the stage was being set up（主詞＋動詞），所以要用從屬連接詞；語意上兩件事同時發生，選 (B) as（當…的時候）。(A) in order to 後面接原形動詞；(C) during 是介系詞，只能接名詞（during the setup）；(D) unless（除非）語意不合。", "tags": ["連接詞", "從屬連接詞"]}, {"id": "國學閱讀綠本 第五回合#Q125", "src": "國學閱讀綠本 第五回合", "no": "Q125", "q": "By recycling batteries rather than discarding them, it is possible to ______ the amount of toxic materials entering landfills.", "opts": ["seize", "reduce", "satisfy", "reserve"], "ans": 1, "exp": "句意是「回收電池而不是丟棄，就有可能減少進入掩埋場的有毒物質量。」空格後受詞是 the amount of...（數量），前半句提到回收而非丟棄，語意上應是「減少」，因此選 (B) reduce。(A) seize（抓住、查扣）、(C) satisfy（滿足）、(D) reserve（預留、保留）都無法與「有毒物質的量」形成合理搭配。", "tags": ["字彙", "動詞"]}, {"id": "國學閱讀綠本 第五回合#Q130", "src": "國學閱讀綠本 第五回合", "no": "Q130", "q": "Failing to file your tax form ______ may lead to an amendment request from the National Tax Office.", "opts": ["nearly", "moderately", "narrowly", "properly"], "ans": 3, "exp": "句意是「沒有正確地申報稅表，可能會收到國稅局要求更正的通知。」空格是修飾動詞 file（申報）的副詞；既然結果是被要求更正，原因就是「沒有依規定正確申報」，因此選 (D) properly（適當地、正確地）。(A) nearly（幾乎）、(B) moderately（適度地）、(C) narrowly（勉強地、狹隘地）語意都與申報表格不合。", "tags": ["字彙", "副詞"]}, {"id": "國學閱讀綠本 第六回合#Q104", "src": "國學閱讀綠本 第六回合", "no": "Q104", "q": "Organizing a new product launch requires ______ among departments.", "opts": ["cooperate", "cooperation", "to cooperate", "cooperative"], "ans": 1, "exp": "句意是「籌辦新產品發表會需要各部門之間的合作。」判斷關鍵在空格要當及物動詞 requires 的受詞，且後面接介系詞片語 among departments，所以必須填名詞，選 (B) cooperation（合作）。(A) cooperate 是動詞原形；(C) to cooperate 是不定詞，require 要用 require somebody to do 的結構才會出現不定詞，這裡沒有受詞；(D) cooperative 是形容詞（合作的），不能單獨當受詞。", "tags": ["詞性", "名詞"]}, {"id": "國學閱讀綠本 第六回合#Q109", "src": "國學閱讀綠本 第六回合", "no": "Q109", "q": "A trade show representative called each participant a month before the event ______ their attendance.", "opts": ["confirm", "to confirm", "will confirm", "is confirming"], "ans": 1, "exp": "句意是「展覽會的接待人員在活動前一個月致電每位參加者，以確認他們是否出席。」句子已有主要動詞 called，空格處要表達「打電話的目的」，因此用不定詞 to confirm 當目的副詞，選 (B)。(A) confirm 是原形動詞，會造成一個句子出現兩個動詞卻沒有連接詞；(C) will confirm、(D) is confirming 同樣是完整的動詞形式，前面沒有 and 或連接詞可以連接兩個子句。", "tags": ["詞性", "不定詞"]}, {"id": "國學閱讀綠本 第六回合#Q111", "src": "國學閱讀綠本 第六回合", "no": "Q111", "q": "The art historian did copious research while trying to ______ the painting as an original.", "opts": ["adapt", "generate", "authenticate", "commission"], "ans": 2, "exp": "句意是「這位藝術史學家做了大量研究，試圖鑑定這幅畫作為真跡。」判斷關鍵在受詞結構 ______ the painting as an original（把畫作認定為真品），需要「證明…為真、鑑定真偽」的動詞，選 (C) authenticate。(A) adapt（改編、使適應）、(B) generate（產生、生成）語意不合；(D) commission（委託創作）指出資請人製作，與「做研究驗證真偽」的情境相反。", "tags": ["字彙", "動詞"]}, {"id": "國學閱讀綠本 第六回合#Q114", "src": "國學閱讀綠本 第六回合", "no": "Q114", "q": "Thanks to hours of practice, the sales team was able to ______ present its proposal to the client.", "opts": ["confide", "confident", "confiding", "confidently"], "ans": 3, "exp": "句意是「多虧了數小時的練習，業務團隊得以自信地向客戶提案。」判斷關鍵在空格夾在 able to 與原形動詞 present 之間，要修飾動詞就得用副詞，選 (D) confidently（有自信地）。(A) confide（吐露秘密）意思不對，且會變成兩個原形動詞連用；(B) confident 是形容詞，不能修飾動詞；(C) confiding 是分詞／形容詞（信賴的），同樣不能修飾 present。", "tags": ["詞性", "副詞"]}, {"id": "國學閱讀綠本 第六回合#Q117", "src": "國學閱讀綠本 第六回合", "no": "Q117", "q": "The escalators at Davidson Station are subject to ______ inspection to ensure they are working properly.", "opts": ["routinely", "routine", "routines", "routinize"], "ans": 1, "exp": "句意是「Davidson 車站的電扶梯須接受例行檢查，以確保運作正常。」判斷關鍵在 be subject to 的 to 是介系詞，後面接名詞 inspection，空格要修飾這個名詞，因此填形容詞 (B) routine（例行的）。(A) routinely 是副詞，不能修飾名詞；(C) routines 是複數名詞，兩個名詞並排無法構成合理的複合名詞；(D) routinize 是動詞（使例行化）。", "tags": ["詞性", "形容詞"]}, {"id": "國學閱讀綠本 第六回合#Q118", "src": "國學閱讀綠本 第六回合", "no": "Q118", "q": "______ resident of West Bay who earns less than $25,000 a year is eligible to apply for housing assistance.", "opts": ["Most", "Those", "Any", "All"], "ans": 2, "exp": "句意是「任何年收入低於 25,000 美元的西灣居民，都符合申請住房補助的資格。」判斷關鍵在主詞是單數可數名詞 resident，主要動詞也是單數的 is eligible，能直接搭配單數可數名詞的限定詞只有 (C) Any（任何一位）。(A) Most、(D) All 後面要接複數名詞（most/all residents）或不可數名詞；(B) Those 是複數指示詞，也要接複數名詞。", "tags": ["文法", "限定詞"]}, {"id": "國學閱讀綠本 第六回合#Q122", "src": "國學閱讀綠本 第六回合", "no": "Q122", "q": "Due to ______ economic conditions, the company may decide to stop hiring employees.", "opts": ["worst", "worsen", "worsens", "worsening"], "ans": 3, "exp": "句意是「由於經濟狀況持續惡化，公司可能決定停止招聘員工。」Due to 是介系詞片語，後面接名詞 economic conditions，空格要當形容詞修飾這個名詞，選 (D) worsening（日益惡化的，現在分詞當形容詞）。(A) worst 是最高級，前面必須有 the；(B) worsen 是動詞原形、(C) worsens 是第三人稱單數動詞，介系詞後面不能接動詞。", "tags": ["詞性", "分詞"]}, {"id": "國學閱讀綠本 第七回合#Q107", "src": "國學閱讀綠本 第七回合", "no": "Q107", "q": "Investing in safe financial products can protect ______ from experiencing significant losses.", "opts": ["retire", "retiree", "retirees", "retired"], "ans": 2, "exp": "句意是「投資安全的金融商品，可以保護退休人士免於承受重大損失。」判斷關鍵在空格要當及物動詞 protect 的受詞，必須是名詞；protect somebody from V-ing 的對象是「人」，且這裡泛指一般退休族，用複數 (C) retirees（退休人士）最合適。(A) retire 是動詞原形；(B) retiree 是單數可數名詞，前面沒有 a／the 不能單獨使用；(D) retired 是形容詞（退休的），不能當受詞。", "tags": ["詞性", "名詞"]}, {"id": "國學閱讀綠本 第七回合#Q109", "src": "國學閱讀綠本 第七回合", "no": "Q109", "q": "The flight attendant asked that all headphones ______ returned before landing.", "opts": ["are", "be", "were", "to be"], "ans": 1, "exp": "句意是「空服員要求所有耳機在降落前歸還。」判斷關鍵在 ask that... 這類表「要求、建議、命令」的動詞，後面 that 子句要用假設語氣，動詞一律用原形（should 省略），這裡是被動語態，所以填 (B) be returned。(A) are、(C) were 是有時態變化的 be 動詞，不符合假設語氣的原形規則；(D) to be 是不定詞，that 子句裡必須有完整的動詞。 ▍【同類字整理】除了 ask，這三類字後面的 that 子句都要用原形： ①動詞（口訣：一堅持、二建議、三要求、四命令）── 要求類 ask / request / require / demand / urge；建議類 suggest / recommend / propose / advise；堅持類 insist；命令規定類 order / command / direct / mandate / stipulate；其他 prefer / desire / move（動議）。例：The manager insisted that the report BE submitted by Friday.（不是 is／was） ②形容詞，句型 It is + adj + that + S + 原形 ── essential / important / imperative / necessary / vital / crucial / urgent / advisable / mandatory / desirable / best。例：It is imperative that every employee ATTEND the safety briefing.（不是 attends） ③名詞（上面動詞的名詞形，接同位語 that 子句）── suggestion / recommendation / request / demand / proposal / requirement / insistence / order。例：Her recommendation that the deadline BE extended was approved. ▍【兩個陷阱】㊀被動語態時只留 be：像本題 that all headphones BE returned，空格填 be，不是 are／were／to be。㊁suggest、insist 不一定用原形 ── 當它們表示「顯示、暗示」或「主張某個既成事實」時照正常時態走：The data suggests that sales HAVE declined.（顯示事實）、He insisted that he WAS innocent.（主張事實）；但 He insisted that she LEAVE.（要求她離開）就要用原形。判斷法：那件事還沒發生、是希望對方去做的 → 用原形；已經是事實、只是在陳述 → 正常時態。", "tags": ["假設語氣", "動詞原形"]}, {"id": "國學閱讀綠本 第七回合#Q112", "src": "國學閱讀綠本 第七回合", "no": "Q112", "q": "Residents are deeply divided on ______ to support during the next mayoral election.", "opts": ["that", "whom", "which", "whose"], "ans": 1, "exp": "句意是「居民對於下屆市長選舉要支持誰，意見嚴重分歧。」判斷關鍵在介系詞 on 後面接的是「疑問詞＋不定詞」結構，而空格同時要當 support 的受詞；選舉支持的對象是人，用受格疑問詞 (B) whom。(A) that 不能引導疑問詞＋不定詞；(C) which 指「哪一個」，後面通常要接名詞或有明確的選項範圍，且不用於泛指人選；(D) whose 是所有格，後面必須接名詞（whose candidate）。", "tags": ["代名詞", "疑問詞"]}, {"id": "國學閱讀綠本 第七回合#Q113", "src": "國學閱讀綠本 第七回合", "no": "Q113", "q": "Studies show that managers ______ in conflict resolution build stronger and more effective teams.", "opts": ["signed", "submitted", "trained", "thanked"], "ans": 2, "exp": "句意是「研究顯示，受過衝突處理訓練的主管能建立更穩固、更有效率的團隊。」判斷關鍵在空格是修飾 managers 的過去分詞，後面接介系詞 in，要能形成 be trained in something（在某方面受過訓練）的搭配，選 (C) trained。(A) signed（簽署的）、(B) submitted（被提交的）語意不合，主詞是人；(D) thanked（被感謝的）雖然可以用於人，但與 in conflict resolution 及「帶出更強團隊」的因果關係不合。", "tags": ["字彙", "分詞"]}, {"id": "國學閱讀綠本 第七回合#Q114", "src": "國學閱讀綠本 第七回合", "no": "Q114", "q": "New employees of Hislop Industries must complete ______ training courses within their first month of employment.", "opts": ["attentive", "intelligent", "permanent", "mandatory"], "ans": 3, "exp": "句意是「Hislop 工業的新進員工必須在到職第一個月內完成必修的訓練課程。」判斷關鍵在句中的 must complete（必須完成）與 within their first month（期限），呼應「強制性的」課程，選 (D) mandatory（強制的、必修的）。(A) attentive（專注的）用來形容人；(B) intelligent（聰明的）也是形容人；(C) permanent（永久的）與有期限的訓練課程矛盾。", "tags": ["字彙", "形容詞"]}, {"id": "國學閱讀綠本 第七回合#Q126", "src": "國學閱讀綠本 第七回合", "no": "Q126", "q": "The director of operations aims to ______ the aquarium with a state-of-the-art filtration system.", "opts": ["oblige", "equip", "certify", "revolve"], "ans": 1, "exp": "句意是「營運總監打算為水族館配備最先進的過濾系統。」判斷關鍵在 ______ A with B 的結構，要能表示「為 A 配備 B」，選 (B) equip（配備、裝設）。(A) oblige（迫使）常用 oblige somebody to do；(C) certify（認證）受詞是資格或文件，不搭配 with 設備；(D) revolve（旋轉）是不及物動詞，後面不能直接接受詞。", "tags": ["字彙", "動詞"]}, {"id": "國學閱讀綠本 第七回合#Q130", "src": "國學閱讀綠本 第七回合", "no": "Q130", "q": "Restaurants have been opening near the new apartment complex with increasing ______ to serve the residents.", "opts": ["disagreement", "frequency", "knowledge", "limitation"], "ans": 1, "exp": "句意是「為了服務這些住戶，新公寓大樓附近的餐廳開幕得越來越頻繁。」判斷關鍵在 with increasing ______ 是修飾「開店」這個動作的副詞片語，與 have been opening（持續發生）呼應的是「次數」，選 (B) frequency（頻率），with increasing frequency 是固定用法，等於 more and more frequently。(A) disagreement（意見不合）、(C) knowledge（知識）、(D) limitation（限制）都無法說明開店的頻繁程度。", "tags": ["字彙", "名詞"]}, {"id": "國學閱讀綠本 第八回合#Q110", "src": "國學閱讀綠本 第八回合", "no": "Q110", "q": "Mr. McGuire needs only one more issue of a rare comic book series to have a ______ set.", "opts": ["completion", "complete", "completer", "completeness"], "ans": 1, "exp": "句意是「McGuire 先生只要再多一期，就能湊齊這套稀有漫畫。」判斷關鍵在空格夾在冠詞 a 與名詞 set 之間，這個位置只能放形容詞，選 (B) complete（完整的）。(A) completion（完成）是名詞，a completion set 兩個名詞硬湊不成合理的複合名詞；(C) completer 不是常用的形容詞比較級（complete 是「完整」這種絕對概念，本來就不比較）；(D) completeness（完整性）也是名詞，不能修飾 set。", "tags": ["詞性", "形容詞"]}, {"id": "國學閱讀綠本 第八回合#Q114", "src": "國學閱讀綠本 第八回合", "no": "Q114", "q": "In the event that the competition results in a tie, the prize money will be divided ______ both contestants.", "opts": ["within", "off", "along", "between"], "ans": 3, "exp": "句意是「萬一比賽結果平手，獎金將由兩位參賽者平分。」判斷關鍵在 a tie（平手）與 both contestants（兩位參賽者）點明只有「兩個人」，分配給兩者之間用 (D) between。(A) within（在…之內）用於範圍或期限；(B) off（離開、脫離）語意不合；(C) along（沿著）用於線狀的路徑。補充：三者以上平分要用 among，例如 divided among the three winners。", "tags": ["介系詞"]}, {"id": "國學閱讀綠本 第八回合#Q116", "src": "國學閱讀綠本 第八回合", "no": "Q116", "q": "Mr. Chen has nearly 30 years of advertising experience, making him a ______ professional in his field.", "opts": ["seasons", "seasonal", "seasoned", "seasonally"], "ans": 2, "exp": "句意是「陳先生有將近 30 年的廣告資歷，使他成為業界經驗老到的專業人士。」判斷關鍵在空格在冠詞 a 與名詞 professional 之間要放形容詞，而且要呼應前面的 30 年資歷，選 (C) seasoned（經驗豐富的、老練的）。(A) seasons 是名詞複數或動詞三單，不能修飾名詞；(B) seasonal 是「季節性的」，a seasonal professional 變成「季節性上工的人」，與 30 年資歷的稱讚語氣不合；(D) seasonally 是副詞，不能修飾名詞。", "tags": ["字彙", "形容詞"]}, {"id": "國學閱讀綠本 第八回合#Q120", "src": "國學閱讀綠本 第八回合", "no": "Q120", "q": "The town of Hamilton has seven parks, all of ______ have hosted outdoor concerts at one time or another.", "opts": ["them", "those", "which", "theirs"], "ans": 2, "exp": "句意是「Hamilton 鎮有七座公園，這些公園都曾在不同時期舉辦過戶外音樂會。」判斷關鍵在逗號後面出現了另一個動詞 have hosted，卻沒有連接詞，因此空格必須是能兼作連接詞的關係代名詞；先行詞是 seven parks（物），用 (C) which，形成 all of which 引導的非限定子句。(A) them、(B) those、(D) theirs 都只是代名詞，沒有連接功能，會造成兩個子句連寫（若要用 them，前面得改成 and all of them have hosted…）。", "tags": ["關係代名詞", "非限定"]}, {"id": "國學閱讀綠本 第八回合#Q127", "src": "國學閱讀綠本 第八回合", "no": "Q127", "q": "During his acceptance speech for the Businessperson of the Year Award, Mr. Gordon expressed ______ for his dedicated team members.", "opts": ["commitment", "interest", "tribute", "appreciation"], "ans": 3, "exp": "句意是「Gordon 先生在年度企業人士獎的得獎感言中，表達了對團隊成員盡心付出的感謝。」判斷關鍵在得獎感言＋dedicated team members（盡心的團隊成員），要表達的是謝意，且 express appreciation for something／somebody 是固定搭配，選 (D) appreciation（感謝、賞識）。(A) commitment（承諾、投入）搭配的介系詞是 to，express commitment to；(B) interest（興趣）搭配 in，且對自己團隊「表達興趣」語意奇怪；(C) tribute（讚頌）不與 express 連用，慣用說法是 pay tribute to somebody。", "tags": ["字彙", "名詞"]}, {"id": "國學閱讀綠本 第八回合#Q128", "src": "國學閱讀綠本 第八回合", "no": "Q128", "q": "Visitors are not allowed in certain sections of the building, ______ are they permitted to wander around without a guide.", "opts": ["so", "during", "nor", "though"], "ans": 2, "exp": "句意是「訪客不得進入大樓的某些區域，也不准在沒有導覽人員陪同下四處走動。」判斷關鍵在空格後面是 are they permitted 的倒裝語序（be 動詞跑到主詞前面），這是否定副詞或 nor 置句首才會出現的結構；前一句是否定句，後面要接續另一個否定，用 (C) nor（也不）。(A) so 表示結果，且 so 開頭要用正常語序；(B) during 是介系詞，後面只能接名詞；(D) though 是從屬連接詞，後面接的子句不倒裝，語意上也沒有轉折關係。", "tags": ["連接詞", "倒裝"]}, {"id": "國學閱讀綠本 第九回合#Q103", "src": "國學閱讀綠本 第九回合", "no": "Q103", "q": "Thanks to a city council budget surplus, it is ______ possible that Davondale Bridge will be replaced this year.", "opts": ["certain", "certainty", "certainly", "certitude"], "ans": 2, "exp": "句意是「多虧市議會預算有結餘，Davondale 橋今年很可能會被換新。」判斷關鍵在句型已經是完整的 it is + 形容詞 possible + that 子句（虛主詞句型），空格夾在 be 動詞與形容詞 possible 之間，這個位置只能放修飾形容詞的副詞，選 (C) certainly（的確、確實）。(A) certain 是形容詞，it is certain possible 兩個形容詞並排不成立（要說 it is certain that…）；(B) certainty（確定性）與 (D) certitude（確信）都是名詞，放進來變成 it is certainty possible，句子結構壞掉。", "tags": ["詞性", "副詞"]}, {"id": "國學閱讀綠本 第九回合#Q107", "src": "國學閱讀綠本 第九回合", "no": "Q107", "q": "Attendees found the computer tutorial offered by Offenburg Community Center to be ______ helpful.", "opts": ["fast", "enough", "quite", "soon"], "ans": 2, "exp": "句意是「與會者覺得 Offenburg 社區中心提供的電腦教學相當有幫助。」判斷關鍵在空格要修飾後面的形容詞 helpful，需要一個程度副詞，選 (C) quite（相當、頗）。(B) enough 當副詞修飾形容詞時必須「後置」，要寫成 helpful enough，不能放在前面；(A) fast（快速地）與 (D) soon（很快、不久）講的是速度和時間，不能用來表示「有幫助的程度」。補充：這裡的 find + 受詞 + to be + 形容詞是「覺得某物是…」的句型。", "tags": ["字彙", "副詞"]}, {"id": "國學閱讀綠本 第九回合#Q108", "src": "國學閱讀綠本 第九回合", "no": "Q108", "q": "To find his printer's model number, Mr. Jansen turned it ______ and checked the bottom.", "opts": ["past", "against", "in", "over"], "ans": 3, "exp": "句意是「為了找印表機的型號，Jansen 先生把它翻過來檢查底部。」判斷關鍵在後半句的 checked the bottom（檢查底部），要先把機器「翻面」才看得到底部，turn something over 就是「把某物翻過來」，選 (D) over。(A) turn past 沒有這個搭配；(B) turn against 是「反目、倒戈」，語意不合；(C) turn in 是「繳交、上交」（turn in a report），也可指「就寢」，都與翻面無關。", "tags": ["介系詞", "片語"]}, {"id": "國學閱讀綠本 第九回合#Q109", "src": "國學閱讀綠本 第九回合", "no": "Q109", "q": "Earth Preserve hopes that everyone ______ to a fund-raiser held in the coming week.", "opts": ["contributing", "will contribute", "contributed", "had contributed"], "ans": 1, "exp": "句意是「Earth Preserve 希望大家都能為下週舉辦的募款活動出一份力。」判斷關鍵在時間副詞 in the coming week（在接下來這一週）指向未來，而且 hope 後面的 that 子句本來就常接未來式，選 (B) will contribute。(A) contributing 是分詞，that 子句缺少真正的動詞；(C) contributed 是過去式、(D) had contributed 是過去完成式，都與「還沒發生的募款活動」時間矛盾。", "tags": ["時態", "未來式"]}, {"id": "國學閱讀綠本 第九回合#Q110", "src": "國學閱讀綠本 第九回合", "no": "Q110", "q": "Several local ski lodges have delayed opening ______ mid-November due to the warm weather.", "opts": ["about", "despite", "until", "across"], "ans": 2, "exp": "句意是「因為天氣偏暖，好幾家當地滑雪旅館把開幕延到十一月中。」判斷關鍵在動詞 delay（延後）搭配的是「延到某個時間點」，用表示持續到某時間的 (C) until。(A) about 接時間是「大約」，delay opening about mid-November 少了「延到」的方向性；(B) despite（儘管）是讓步介系詞，語意不合，何況原因已由 due to 交代；(D) across 表示橫越空間或跨越一段範圍，不用來標記單一時間點。", "tags": ["介系詞"]}, {"id": "國學閱讀綠本 第九回合#Q114", "src": "國學閱讀綠本 第九回合", "no": "Q114", "q": "As a result of an exclusive agreement, the drink Nitro-Sip is available ______ at Duggarti Foods.", "opts": ["densely", "fully", "solely", "fairly"], "ans": 2, "exp": "句意是「由於一紙獨家協議，Nitro-Sip 這款飲料只在 Duggarti Foods 買得到。」判斷關鍵在 exclusive agreement（獨家協議）這個提示，後面必須呼應「僅此一家」，選 (C) solely（僅、唯獨）。(A) densely（密集地）用於人口或植被；(B) fully（完全地）修飾的是程度，available fully 語意空泛且不呼應獨家；(D) fairly（相當地；公平地）兩個意思放進來都不通。", "tags": ["字彙", "副詞"]}, {"id": "國學閱讀綠本 第九回合#Q116", "src": "國學閱讀綠本 第九回合", "no": "Q116", "q": "Though the ______ findings suggested that the medication was effective, further research proved otherwise.", "opts": ["congested", "upcoming", "hazardous", "original"], "ans": 3, "exp": "句意是「雖然最初的研究結果顯示這款藥有效，後續研究卻證明並非如此。」判斷關鍵在 Though 帶出的對比：空格的研究結果和後面的 further research（進一步研究）是「先前 vs 後續」的時間對照，選 (D) original（最初的、原本的）。(A) congested（壅塞的）用於交通或鼻塞；(B) upcoming（即將到來的）方向相反，還沒出來的結果不可能已經 suggested；(C) hazardous（危險的）與研究結果搭不上，也對比不出來。", "tags": ["字彙", "形容詞"]}, {"id": "國學閱讀綠本 第九回合#Q119", "src": "國學閱讀綠本 第九回合", "no": "Q119", "q": "Ahead of his retirement, Director John Bailey ______ his colleague Vanessa Gail as his successor.", "opts": ["consented", "estimated", "amended", "nominated"], "ans": 3, "exp": "句意是「John Bailey 主任在退休前提名同事 Vanessa Gail 接任。」判斷關鍵在 as his successor（作為接班人）這個補語，需要 nominate somebody as／for something（提名某人擔任…）的搭配，選 (D) nominated。(A) consented（同意）是不及物動詞，要說 consent to something，不能直接接受詞；(B) estimated（估計）接的是數量或價值；(C) amended（修訂）的受詞是文件、法規、合約這類東西，不能修訂「人」。", "tags": ["字彙", "動詞"]}, {"id": "國學閱讀綠本 第九回合#Q120", "src": "國學閱讀綠本 第九回合", "no": "Q120", "q": "The company's new workplace safety policy is high ______ the agenda for tomorrow's meeting.", "opts": ["of", "to", "at", "on"], "ans": 3, "exp": "句意是「公司新的職場安全政策在明天會議的議程上排在前面（是重點項目）。」判斷關鍵在 high on the agenda 是固定搭配，表示「列為優先事項」，選 (D) on；議程上的項目本來就用 on the agenda。(A) of、(B) to、(C) at 都不與 agenda 這樣連用，at the agenda 尤其不存在。補充：同義說法有 a top priority、at the top of the agenda。", "tags": ["介系詞", "片語"]}, {"id": "國學閱讀綠本 第九回合#Q122", "src": "國學閱讀綠本 第九回合", "no": "Q122", "q": "Students are ______ arguing for the renovation of Central Library, which is now over 50 years old.", "opts": ["immeasurably", "strongly", "mutually", "inadvertently"], "ans": 1, "exp": "句意是「學生們強烈主張中央圖書館應該整修，這棟建築已有超過 50 年歷史。」判斷關鍵在空格修飾 arguing for（主張、力挺），要表達主張的強度，argue strongly for something 是常見搭配，選 (B) strongly（強烈地）。(A) immeasurably（無法衡量地）用來修飾程度差異，如 immeasurably better；(C) mutually（互相地）需要雙方互動，如 mutually beneficial；(D) inadvertently（無意間、不小心地）與「力爭」的刻意行為矛盾。", "tags": ["字彙", "副詞"]}, {"id": "國學閱讀綠本 第九回合#Q123", "src": "國學閱讀綠本 第九回合", "no": "Q123", "q": "______ they are entered into the payroll system, new employees must provide the finance department with some banking information.", "opts": ["As if", "During", "Before", "Instead of"], "ans": 2, "exp": "句意是「新進員工在被登錄進薪資系統之前，必須先向財務部提供銀行資料。」判斷關鍵在空格後面是完整子句 they are entered…，需要從屬連接詞，且先給銀行資料才能建檔，時間順序上用 (C) Before。(B) During 與 (D) Instead of 都是介系詞，後面只能接名詞或動名詞，不能接子句；(A) As if（彷彿）雖是連接詞，但表示「好像…一樣」的比擬，語意不合。", "tags": ["連接詞", "副詞子句"]}, {"id": "國學閱讀綠本 第九回合#Q125", "src": "國學閱讀綠本 第九回合", "no": "Q125", "q": "Due to the success of his prototypes, the inventor currently has a ______ reputation for innovation.", "opts": ["grown", "growing", "grower", "growth"], "ans": 1, "exp": "句意是「由於原型機大獲成功，這位發明家在創新方面的名聲正日益上升。」判斷關鍵在空格在冠詞 a 與名詞 reputation 之間要放修飾語，名聲是「主動地不斷擴大」，用現在分詞 (B) growing（日漸增長的）。(A) grown 是過去分詞，帶被動或完成語氣，a grown reputation 不自然（grown 多用於 a grown man 這種「長大成人的」）；(C) grower（種植者）是人物名詞；(D) growth（成長）是名詞，growth 雖可修飾名詞如 growth rate，但 a growth reputation 不成立。", "tags": ["詞性", "分詞"]}, {"id": "國學閱讀綠本 第九回合#Q127", "src": "國學閱讀綠本 第九回合", "no": "Q127", "q": "The ______ of LRB Pharmaceuticals and Hough Laboratories may result in the elimination of some positions.", "opts": ["merger", "potential", "dedication", "obligation"], "ans": 0, "exp": "句意是「LRB 製藥與 Hough 實驗室的合併，可能導致部分職位被裁撤。」判斷關鍵在 A and B 兩家公司並列，加上後果是裁員，指的是企業合併，the merger of A and B 是固定說法，選 (A) merger（合併）。(B) potential（潛力）是抽象特質，不會由兩家公司「的」共同擁有並導致裁員；(C) dedication（奉獻、投入）語意上不會造成職位消失；(D) obligation（義務）通常搭配 to do something，也接不上裁員的因果。", "tags": ["字彙", "名詞"]}, {"id": "國學閱讀綠本 第九回合#Q128", "src": "國學閱讀綠本 第九回合", "no": "Q128", "q": "Amberview Beach Resort is a popular summer destination, but it is open for business all ______ the year.", "opts": ["among", "without", "through", "beyond"], "ans": 2, "exp": "句意是「Amberview 海灘度假村是熱門的夏日去處，但它整年都營業。」判斷關鍵在 but 帶出的對比：不只夏天，而是「一整年從頭到尾」，all through the year 表示貫穿整段期間，選 (C) through。(A) among（在…之中）用於三者以上的群體；(B) without（沒有）語意不合；(D) beyond（超過、在…之外）指的是越過某界線之後，不是涵蓋整年。補充：同義說法有 all year round、throughout the year。", "tags": ["介系詞"]}, {"id": "國學閱讀綠本 第九回合#Q129", "src": "國學閱讀綠本 第九回合", "no": "Q129", "q": "Ms. Ross acquired the ______ number of new customers in May, falling behind all the other sales representatives.", "opts": ["steadiest", "brightest", "longest", "smallest"], "ans": 3, "exp": "句意是「Ross 女士五月開發到的新客戶數量最少，落後其他所有業務代表。」判斷關鍵在 falling behind all the other sales representatives（落後所有其他業務）點明她墊底，而修飾 number（數量）要用大小，選 (D) smallest（最少的）。(A) steadiest（最穩定的）與「落後」不呼應；(B) brightest（最明亮的、最聰明的）不修飾數量；(C) longest（最長的）用於長度或時間，不用來形容數目多寡。", "tags": ["字彙", "最高級"]}, {"id": "國學閱讀綠本 第九回合#Q130", "src": "國學閱讀綠本 第九回合", "no": "Q130", "q": "Completing an important project under a time ______ calls for careful scheduling.", "opts": ["constraint", "relief", "quality", "proposal"], "ans": 0, "exp": "句意是「要在時間壓力下完成重要專案，需要仔細安排進度。」判斷關鍵在後面說需要 careful scheduling（仔細排程），代表時間吃緊，time constraint（時間限制、時間壓力）是固定搭配，選 (A) constraint。(B) relief（緩解、寬慰）方向相反，時間充裕就不必精算排程；(C) quality（品質）與 time 湊不成合理複合名詞；(D) proposal（提案）是待審核的計畫書，不能說 under a time proposal。", "tags": ["字彙", "名詞"]}];
